K = {
 # ------------------------------------------------------------------ cit12 la phrase de passe
 "hist.cit12.0.dit": T("Voici une liste de mots (des noms de créatures). Combien y en a-t-il ?", "Here is a list of words (creature names). How many are there?", "Aquí hay una lista de palabras (nombres de criaturas). ¿Cuántas hay?", "Hier ist eine Wortliste (Kreaturennamen). Wie viele sind es?", "Ecco una lista di parole (nomi di creature). Quante sono?", "Aqui está uma lista de palavras (nomes de criaturas). Quantas são?", "Вот список слов (имена существ). Сколько их?", "这是一张单词表（都是生物的名字）。一共有几个？", "言葉のリスト（生き物の名前）があるよ。いくつある？", "यह शब्दों की सूची है (जीवों के नाम)। कितने हैं?", "هذه قائمة كلمات (أسماء مخلوقات). كم عددها؟", "এই নাও শব্দের তালিকা (প্রাণীদের নাম)। কয়টা আছে?", "Ini daftar kata (nama makhluk). Ada berapa?", "یہ لفظوں کی فہرست ہے (جانوروں کے نام)۔ کتنے ہیں؟"),
 "hist.cit12.0.bravo": T("128 mots. Retiens ce nombre : on va s'en servir pour mesurer la force d'une phrase de passe.", "128 words. Remember that number: we'll use it to measure a passphrase's strength.", "128 palabras. Recuerda el número: lo usaremos para medir la fuerza de una frase de contraseña.", "128 Wörter. Merk dir die Zahl: Damit messen wir die Stärke einer Passphrase.", "128 parole. Ricorda il numero: ci servirà a misurare la forza di una passphrase.", "128 palavras. Guarde esse número: vamos usar para medir a força de uma frase-senha.", "128 слов. Запомни число: им мы измерим силу парольной фразы.", "128 个词。记住这个数：我们要用它来量密码短语有多强。", "128語。この数をおぼえておこう：パスフレーズの強さをはかるのに使う。", "128 शब्द। यह संख्या याद रखो: इससे पासफ़्रेज़ की ताक़त नापेंगे।", "128 كلمة. تذكّر هذا الرقم: سنقيس به قوة عبارة المرور.", "১২৮টা শব্দ। সংখ্যাটা মনে রাখো: এ দিয়ে পাসফ্রেজের জোর মাপব।", "128 kata. Ingat angka ini: kita pakai untuk mengukur kekuatan frasa sandi.", "128 لفظ۔ یہ عدد یاد رکھو: اس سے پاس فریز کی طاقت ناپیں گے۔"),
 "hist.cit12.0.adulte": T("wc -l compte les lignes. 128 = 2⁷ : chaque mot tiré au hasard apporte 7 bits d'incertitude.", "wc -l counts lines. 128 = 2⁷: each randomly drawn word adds 7 bits of uncertainty.", "wc -l cuenta líneas. 128 = 2⁷: cada palabra al azar aporta 7 bits de incertidumbre.", "wc -l zählt Zeilen. 128 = 2⁷: Jedes zufällig gezogene Wort bringt 7 Bit Unsicherheit.", "wc -l conta le righe. 128 = 2⁷: ogni parola estratta a caso porta 7 bit di incertezza.", "wc -l conta linhas. 128 = 2⁷: cada palavra sorteada traz 7 bits de incerteza.", "wc -l считает строки. 128 = 2⁷: каждое случайное слово даёт 7 бит неопределённости.", "wc -l 数行数。128 = 2⁷：每个随机抽出的词带来 7 比特的不确定性。", "wc -l は行を数える。128 = 2⁷：でたらめに選んだ1語ごとに7ビットの不確かさが加わる。", "wc -l पंक्तियाँ गिनता है। 128 = 2⁷: हर रैंडम शब्द 7 बिट अनिश्चितता जोड़ता है।", "يعدّ wc -l الأسطر. 128 = 2⁷: كل كلمة عشوائية تضيف 7 بتات من الغموض.", "wc -l লাইন গোনে। 128 = 2⁷: এলোমেলো প্রতিটা শব্দ ৭ বিট অনিশ্চয়তা যোগ করে।", "wc -l menghitung baris. 128 = 2⁷: tiap kata acak menambah 7 bit ketidakpastian.", "wc -l سطریں گنتا ہے۔ 128 = 2⁷: ہر بے ترتیب لفظ 7 بٹ غیر یقینی جوڑتا ہے۔"),
 "hist.cit12.1.dit": T("Tire 4 mots au hasard : c'est une phrase de passe d'EXEMPLE. (Ne t'en sers jamais pour de vrai !)", "Draw 4 random words: that's an EXAMPLE passphrase. (Never use it for real!)", "Saca 4 palabras al azar: es una frase de contraseña de EJEMPLO. (¡Nunca la uses de verdad!)", "Zieh 4 zufällige Wörter: eine BEISPIEL-Passphrase. (Nie wirklich benutzen!)", "Estrai 4 parole a caso: è una passphrase d'ESEMPIO. (Non usarla mai davvero!)", "Sorteie 4 palavras: é uma frase-senha de EXEMPLO. (Nunca use de verdade!)", "Вытяни 4 случайных слова: это ПРИМЕР парольной фразы. (Никогда не используй её по-настоящему!)", "随机抽 4 个词：这是一个示例密码短语。（千万别真的拿来用！）", "4語をでたらめに選ぼう：これは「例」のパスフレーズ。（本当には使わないで！）", "4 शब्द रैंडम चुनो: यह उदाहरण पासफ़्रेज़ है। (इसे असल में कभी इस्तेमाल मत करना!)", "اسحب 4 كلمات عشوائيًا: إنها عبارة مرور مثال. (لا تستخدمها حقًا أبدًا!)", "এলোমেলো ৪টা শব্দ টানো: এটা উদাহরণ পাসফ্রেজ। (আসলে কখনো ব্যবহার কোরো না!)", "Ambil 4 kata acak: itu frasa sandi CONTOH. (Jangan pernah dipakai sungguhan!)", "4 لفظ بے ترتیب نکالو: یہ مثالی پاس فریز ہے۔ (اسے اصل میں کبھی استعمال نہ کرنا!)"),
 "hist.cit12.1.bravo": T("4 mots au hasard : facile à retenir pour toi, très dur à deviner pour un glitch.", "4 random words: easy for you to remember, very hard for a glitch to guess.", "4 palabras al azar: fácil de recordar para ti, muy difícil de adivinar para un glitch.", "4 Zufallswörter: leicht für dich zu merken, sehr schwer für einen Glitch zu erraten.", "4 parole a caso: facile da ricordare per te, difficilissima da indovinare per un glitch.", "4 palavras ao acaso: fácil para você lembrar, muito difícil para um glitch adivinhar.", "4 случайных слова: тебе легко запомнить, глитчу очень трудно угадать.", "4 个随机的词：你好记，故障怪很难猜。", "でたらめな4語：きみにはおぼえやすく、グリッチにはとても当てにくい。", "4 रैंडम शब्द: तुम्हारे लिए याद रखना आसान, ग्लिच के लिए अंदाज़ा लगाना बहुत कठिन।", "4 كلمات عشوائية: سهلة الحفظ عليك، صعبة جدًا على الخلل أن يخمّنها.", "৪টা এলোমেলো শব্দ: তোমার মনে রাখা সহজ, গ্লিচের আন্দাজ করা খুব কঠিন।", "4 kata acak: mudah kamu ingat, sangat sulit ditebak glitch.", "4 بے ترتیب لفظ: تمہارے لیے یاد رکھنا آسان، گلچ کے لیے اندازہ لگانا بہت مشکل۔"),
 "hist.cit12.1.adulte": T("shuf mélange les lignes ; -n 4 en garde 4. Le hasard doit être vrai (les gens choisissent mal). Ce sont des exemples : une vraie phrase de passe ne s'écrit jamais dans un jeu.", "shuf shuffles lines; -n 4 keeps 4. The randomness must be real (people choose badly). These are examples: a real passphrase is never typed into a game.", "shuf mezcla las líneas; -n 4 conserva 4. El azar debe ser real (la gente elige mal). Son ejemplos: una frase real nunca se escribe en un juego.", "shuf mischt Zeilen; -n 4 behält 4. Der Zufall muss echt sein (Menschen wählen schlecht). Das sind Beispiele: Eine echte Passphrase tippt man nie in ein Spiel.", "shuf mescola le righe; -n 4 ne tiene 4. Il caso deve essere vero (le persone scelgono male). Sono esempi: una vera passphrase non si scrive mai in un gioco.", "shuf embaralha as linhas; -n 4 fica com 4. O acaso tem de ser verdadeiro (as pessoas escolhem mal). São exemplos: uma frase-senha real nunca se digita num jogo.", "shuf перемешивает строки; -n 4 оставляет 4. Случайность должна быть настоящей (люди выбирают плохо). Это примеры: настоящую фразу никогда не вводят в игре.", "shuf 把行打乱；-n 4 留下 4 行。随机必须是真随机（人挑的往往不好）。这些只是例子：真正的密码短语绝不在游戏里输入。", "shuf は行をまぜ、-n 4 で4行残す。でたらめさは本物でなければならない（人が選ぶとかたよる）。これは例：本物のパスフレーズはゲームに打たない。", "shuf पंक्तियाँ फेंटता है; -n 4 चार रखता है। रैंडमपन असली होना चाहिए (लोग बुरा चुनते हैं)। ये उदाहरण हैं: असली पासफ़्रेज़ खेल में कभी नहीं लिखते।", "يخلط shuf الأسطر؛ ويُبقي -n 4 أربعة. يجب أن تكون العشوائية حقيقية (الناس يختارون بشكل سيئ). هذه أمثلة: لا تُكتب عبارة حقيقية في لعبة أبدًا.", "shuf লাইন ফেটে; -n 4 চারটা রাখে। এলোমেলোটা আসল হতে হবে (মানুষ খারাপ বাছে)। এগুলো উদাহরণ: আসল পাসফ্রেজ কখনো খেলায় লেখা হয় না।", "shuf mengacak baris; -n 4 menyimpan 4. Keacakannya harus sungguhan (orang memilih dengan buruk). Ini contoh: frasa sandi asli tak pernah diketik di permainan.", "shuf سطریں پھینٹتا ہے؛ -n 4 چار رکھتا ہے۔ بے ترتیبی اصل ہونی چاہیے (لوگ برا چنتے ہیں)۔ یہ مثالیں ہیں: اصل پاس فریز کھیل میں کبھی نہیں لکھتے۔"),
 "hist.cit12.2.dit": T("Combien de temps un glitch mettrait-il à deviner ? Demande à la Citadelle de comparer.", "How long would a glitch take to guess? Ask the Citadel to compare.", "¿Cuánto tardaría un glitch en adivinar? Pide a la Ciudadela que compare.", "Wie lange bräuchte ein Glitch zum Erraten? Lass die Zitadelle vergleichen.", "Quanto ci metterebbe un glitch a indovinare? Chiedi alla Cittadella di confrontare.", "Quanto tempo um glitch levaria para adivinhar? Peça à Cidadela para comparar.", "Сколько времени глитч будет угадывать? Попроси Цитадель сравнить.", "故障怪要猜多久？让城堡来比一比。", "グリッチが当てるのにどれくらいかかる？城塞にくらべてもらおう。", "ग्लिच को अंदाज़ा लगाने में कितना समय लगेगा? किले से तुलना करवाओ।", "كم سيستغرق الخلل ليخمّن؟ اطلب من القلعة أن تقارن.", "গ্লিচের আন্দাজ করতে কত সময় লাগবে? দুর্গকে তুলনা করতে বলো।", "Berapa lama glitch menebak? Minta Benteng membandingkan.", "گلچ کو اندازہ لگانے میں کتنا وقت لگے گا؟ قلعے سے موازنہ کرواؤ۔"),
 "hist.cit12.2.bravo": T("Court et compliqué : un instant. 6 mots au hasard : des siècles. La longueur bat les signes bizarres !", "Short and complicated: an instant. 6 random words: centuries. Length beats weird symbols!", "Corta y complicada: un instante. 6 palabras al azar: siglos. ¡La longitud gana a los signos raros!", "Kurz und kompliziert: ein Augenblick. 6 Zufallswörter: Jahrhunderte. Länge schlägt seltsame Zeichen!", "Corta e complicata: un istante. 6 parole a caso: secoli. La lunghezza batte i segni strani!", "Curta e complicada: um instante. 6 palavras ao acaso: séculos. O tamanho vence os sinais esquisitos!", "Короткий и сложный: мгновение. 6 случайных слов: века. Длина побеждает странные символы!", "又短又复杂：一眨眼。6 个随机词：几百年。长度胜过古怪的符号！", "短くてややこしい：一瞬。でたらめな6語：何世紀も。長さはへんな記号に勝つ！", "छोटा और पेचीदा: एक पल। 6 रैंडम शब्द: सदियाँ। लंबाई अजीब चिह्नों से जीतती है!", "قصيرة ومعقدة: لحظة. 6 كلمات عشوائية: قرون. الطول يتفوق على الرموز الغريبة!", "ছোট আর জটিল: এক মুহূর্ত। ৬টা এলোমেলো শব্দ: শত শত বছর। দৈর্ঘ্য অদ্ভুত চিহ্নকে হারায়!", "Pendek dan rumit: sekejap. 6 kata acak: berabad-abad. Panjang mengalahkan simbol aneh!", "چھوٹا اور پیچیدہ: ایک لمحہ۔ 6 بے ترتیب لفظ: صدیاں۔ لمبائی عجیب نشانوں سے جیتتی ہے!"),
 "hist.cit12.2.adulte": T("Hypothèse : un milliard d'essais par seconde contre une empreinte volée. Un mot de passe connu tombe en une fraction de seconde (listes de fuites) ; 6 mots parmi 7776 ≈ 77 bits. Ajoute un gestionnaire de mots de passe et la double authentification.", "Assumption: a billion guesses per second against a stolen hash. A known password falls in a split second (leak lists); 6 words out of 7776 ≈ 77 bits. Add a password manager and two-factor authentication.", "Hipótesis: mil millones de intentos por segundo contra una huella robada. Una contraseña conocida cae en una fracción de segundo (listas de filtraciones); 6 palabras de 7776 ≈ 77 bits. Añade un gestor de contraseñas y la doble autenticación.", "Annahme: eine Milliarde Versuche pro Sekunde gegen einen gestohlenen Hash. Ein bekanntes Passwort fällt in Sekundenbruchteilen (Leak-Listen); 6 Wörter aus 7776 ≈ 77 Bit. Dazu ein Passwortmanager und Zwei-Faktor-Authentifizierung.", "Ipotesi: un miliardo di tentativi al secondo contro un'impronta rubata. Una password nota cade in una frazione di secondo (liste di fughe); 6 parole su 7776 ≈ 77 bit. Aggiungi un gestore di password e l'autenticazione a due fattori.", "Hipótese: um bilhão de tentativas por segundo contra um hash roubado. Uma senha conhecida cai numa fração de segundo (listas de vazamentos); 6 palavras entre 7776 ≈ 77 bits. Some um gerenciador de senhas e a autenticação em dois fatores.", "Допущение: миллиард попыток в секунду против украденного хеша. Известный пароль падает за долю секунды (списки утечек); 6 слов из 7776 ≈ 77 бит. Добавь менеджер паролей и двухфакторную защиту.", "假设：对着被偷走的哈希，每秒试十亿次。常见密码一瞬间就破（泄露清单）；从 7776 个词里选 6 个 ≈ 77 比特。再加上密码管理器和双重验证。", "仮定：盗まれたハッシュに毎秒10億回ためす。よく知られたパスワードは一瞬で破られる（流出リスト）。7776語から6語 ≈ 77ビット。パスワード管理ソフトと二段階認証も使おう。", "मान लो: चुराए हैश पर हर सेकंड एक अरब कोशिशें। जाना-पहचाना पासवर्ड पल भर में टूटता है (लीक सूचियाँ); 7776 में से 6 शब्द ≈ 77 बिट। साथ में पासवर्ड मैनेजर और दो-चरणीय सत्यापन लगाओ।", "الفرضية: مليار محاولة في الثانية ضد بصمة مسروقة. كلمة مرور معروفة تسقط في جزء من الثانية (قوائم التسريبات)؛ 6 كلمات من 7776 ≈ 77 بت. أضف مدير كلمات مرور والتحقق بخطوتين.", "ধরে নাও: চুরি করা হ্যাশে প্রতি সেকেন্ডে একশো কোটি চেষ্টা। পরিচিত পাসওয়ার্ড মুহূর্তে ভাঙে (ফাঁসের তালিকা); ৭৭৭৬টার মধ্যে ৬টা শব্দ ≈ ৭৭ বিট। সাথে পাসওয়ার্ড ম্যানেজার আর দুই-ধাপ যাচাই নাও।", "Asumsi: semiliar tebakan per detik terhadap hash curian. Kata sandi terkenal jebol dalam sekejap (daftar bocoran); 6 kata dari 7776 ≈ 77 bit. Tambahkan pengelola kata sandi dan autentikasi dua faktor.", "فرض کرو: چرائے ہیش پر ہر سیکنڈ ایک ارب کوششیں۔ جانا پہچانا پاس ورڈ پل بھر میں ٹوٹتا ہے (لیک فہرستیں)؛ 7776 میں سے 6 لفظ ≈ 77 بٹ۔ ساتھ پاس ورڈ مینیجر اور دو مرحلہ تصدیق لگاؤ۔"),
 # ------------------------------------------------------------------ cit13 boîte Énumération
 "hist.cit13.0.dit": T("Les boîtes sont des petits mondes-pièges du jeu. Manche 1 : l'enquête (trouver les 2 drapeaux). Manche 2 : le rempart (réparer). Regarde la liste.", "Boxes are little trap-worlds made by the game. Round 1: the investigation (find 2 flags). Round 2: the rampart (repair). Look at the list.", "Las cajas son pequeños mundos-trampa del juego. Ronda 1: la investigación (encontrar 2 banderas). Ronda 2: la muralla (reparar). Mira la lista.", "Kisten sind kleine Fallenwelten des Spiels. Runde 1: die Ermittlung (2 Flaggen finden). Runde 2: der Wall (reparieren). Schau dir die Liste an.", "Le scatole sono piccoli mondi-trappola del gioco. Manche 1: l'indagine (trovare 2 bandiere). Manche 2: il bastione (riparare). Guarda la lista.", "As caixas são pequenos mundos-armadilha do jogo. Rodada 1: a investigação (achar 2 bandeiras). Rodada 2: a muralha (consertar). Veja a lista.", "Коробки — маленькие миры-ловушки игры. Раунд 1: расследование (найти 2 флага). Раунд 2: стена (починить). Посмотри список.", "盒子是游戏做的陷阱小世界。第 1 回合：调查（找 2 面旗）。第 2 回合：城墙（修好它）。看看列表。", "ボックスはゲームが作ったわなの小世界。第1ラウンド：調査（旗を2つ見つける）。第2ラウンド：城壁（直す）。リストを見よう。", "बक्से खेल की बनाई छोटी जाल-दुनिया हैं। पहला दौर: जाँच (2 झंडे ढूँढो)। दूसरा दौर: प्राचीर (ठीक करो)। सूची देखो।", "الصناديق عوالم-فخاخ صغيرة صنعتها اللعبة. الجولة 1: التحقيق (إيجاد علمين). الجولة 2: السور (الإصلاح). انظر القائمة.", "বাক্স হলো খেলার বানানো ছোট্ট ফাঁদ-জগৎ। ১ম দফা: তদন্ত (২টা পতাকা খোঁজো)। ২য় দফা: প্রাচীর (সারাও)। তালিকা দেখো।", "Kotak adalah dunia-jebakan kecil buatan permainan. Babak 1: penyelidikan (temukan 2 bendera). Babak 2: benteng (perbaiki). Lihat daftarnya.", "ڈبے کھیل کی بنائی چھوٹی جال دنیائیں ہیں۔ پہلا دور: تفتیش (2 جھنڈے ڈھونڈو)۔ دوسرا دور: فصیل (ٹھیک کرو)۔ فہرست دیکھو۔"),
 "hist.cit13.0.bravo": T("Trois boîtes faciles pour commencer. On n'attaque QUE les boîtes du jeu : elles t'appartiennent.", "Three easy boxes to start. We attack ONLY the game's boxes: they belong to you.", "Tres cajas fáciles para empezar. Solo atacamos las cajas del juego: te pertenecen.", "Drei leichte Kisten zum Start. Wir greifen NUR die Kisten des Spiels an: Sie gehören dir.", "Tre scatole facili per cominciare. Attacchiamo SOLO le scatole del gioco: ti appartengono.", "Três caixas fáceis para começar. Atacamos SÓ as caixas do jogo: elas são suas.", "Три лёгкие коробки для начала. Атакуем ТОЛЬКО коробки игры: они твои.", "先来三个简单的盒子。我们只攻击游戏里的盒子：它们是你的。", "まずはかんたんなボックス3つ。攻撃していいのはゲームのボックスだけ：きみのものだから。", "शुरुआत के लिए तीन आसान बक्से। हम सिर्फ़ खेल के बक्सों पर हमला करते हैं: वे तुम्हारे हैं।", "ثلاثة صناديق سهلة للبداية. لا نهاجم إلا صناديق اللعبة: إنها لك.", "শুরুতে তিনটা সহজ বাক্স। আমরা শুধু খেলার বাক্সে আক্রমণ করি: এগুলো তোমার।", "Tiga kotak mudah untuk mulai. Kita HANYA menyerang kotak permainan: itu milikmu.", "شروع میں تین آسان ڈبے۔ ہم صرف کھیل کے ڈبوں پر حملہ کرتے ہیں: یہ تمہارے ہیں۔"),
 "hist.cit13.0.adulte": T("Comme sur Root-Me ou Hack The Box : drapeau « user » puis « root » (ici entrée et donjon), puis la correction, vérifiée par l'inspecteur qui rejoue l'attaque.", "Like on Root-Me or Hack The Box: a “user” flag then a “root” flag (here entry and dungeon), then the fix, checked by the inspector who replays the attack.", "Como en Root-Me o Hack The Box: bandera «user» y luego «root» (aquí entrada y mazmorra), luego la corrección, verificada por el inspector que repite el ataque.", "Wie bei Root-Me oder Hack The Box: Flagge „user“, dann „root“ (hier Eingang und Verlies), dann die Korrektur, geprüft vom Inspektor, der den Angriff wiederholt.", "Come su Root-Me o Hack The Box: bandiera «user» poi «root» (qui ingresso e dongione), poi la correzione, verificata dall'ispettore che rigioca l'attacco.", "Como no Root-Me ou Hack The Box: bandeira «user» e depois «root» (aqui entrada e masmorra), depois a correção, conferida pelo inspetor que repete o ataque.", "Как на Root-Me или Hack The Box: флаг «user», затем «root» (здесь вход и донжон), потом исправление, которое проверяет инспектор, повторяя атаку.", "就像 Root-Me 或 Hack The Box：先拿 user 旗，再拿 root 旗（这里叫入口和地牢），然后修好，由检查员重放攻击来验收。", "Root-Me や Hack The Box と同じ：user の旗、つぎに root の旗（ここでは入口と天守）、そのあと修正。検査官が攻撃をやりなおして確かめる。", "Root-Me या Hack The Box जैसा: पहले «user» झंडा फिर «root» (यहाँ प्रवेश और कालकोठरी), फिर सुधार, जिसे निरीक्षक हमला दोहराकर जाँचता है।", "كما في Root-Me أو Hack The Box: علم «user» ثم «root» (هنا الدخول والبرج)، ثم الإصلاح، يتحقق منه المفتش بإعادة الهجوم.", "Root-Me বা Hack The Box-এর মতো: আগে «user» পতাকা, পরে «root» (এখানে ঢোকা আর অন্ধকূপ), তারপর সারানো, যা পরিদর্শক আক্রমণ আবার চালিয়ে যাচাই করে।", "Seperti di Root-Me atau Hack The Box: bendera «user» lalu «root» (di sini masuk dan ruang bawah), lalu perbaikan, diperiksa inspektur yang mengulang serangan.", "Root-Me یا Hack The Box کی طرح: پہلے «user» جھنڈا پھر «root» (یہاں داخلہ اور تہہ خانہ)، پھر درستی، جسے انسپکٹر حملہ دہرا کر جانچتا ہے۔"),
 "hist.cit13.1.dit": T("Boîte « La cave oubliée » : liste TOUT, même ce qui est caché.", "Box “The forgotten cellar”: list EVERYTHING, even what's hidden.", "Caja «El sótano olvidado»: lista TODO, incluso lo oculto.", "Kiste „Der vergessene Keller“: Liste ALLES, auch das Versteckte.", "Scatola «La cantina dimenticata»: elenca TUTTO, anche ciò che è nascosto.", "Caixa «O porão esquecido»: liste TUDO, até o escondido.", "Коробка «Забытый подвал»: выведи ВСЁ, даже скрытое.", "盒子“被遗忘的地窖”：列出全部，连藏起来的也要。", "ボックス「忘れられた地下室」：かくれたものもふくめて全部表示しよう。", "बक्सा «भूला हुआ तहखाना»: सब दिखाओ, छिपा हुआ भी।", "صندوق «القبو المنسي»: اعرض كل شيء، حتى المخفي.", "বাক্স «ভুলে যাওয়া মাটির ঘর»: সব দেখাও, লুকানোগুলোও।", "Kotak «Ruang bawah terlupa»: tampilkan SEMUA, termasuk yang tersembunyi.", "ڈبہ «بھولا ہوا تہہ خانہ»: سب دکھاؤ، چھپا ہوا بھی۔"),
 "hist.cit13.1.bravo": T("Une .cave_oubliee ! Son point la cachait à ls tout court, pas à ls -a.", "A .cave_oubliee! Its dot hid it from plain ls, not from ls -a.", "¡Una .cave_oubliee! Su punto la escondía de ls a secas, no de ls -a.", "Ein .cave_oubliee! Der Punkt versteckte ihn vor ls, nicht vor ls -a.", "Una .cave_oubliee! Il punto la nascondeva a ls semplice, non a ls -a.", "Uma .cave_oubliee! O ponto a escondia do ls simples, não do ls -a.", "Там .cave_oubliee! Точка прятала её от простого ls, но не от ls -a.", "有个 .cave_oubliee！开头的点只能让普通的 ls 看不见，躲不过 ls -a。", ".cave_oubliee がある！点はふつうの ls からはかくすけど、ls -a からはかくせない。", "एक .cave_oubliee! बिंदु ने इसे साधारण ls से छिपाया, ls -a से नहीं।", "‏.cave_oubliee! النقطة أخفتها عن ls العادي، لا عن ls -a.", "একটা .cave_oubliee! বিন্দুটা সাধারণ ls থেকে লুকিয়েছিল, ls -a থেকে নয়।", "Ada .cave_oubliee! Titiknya menyembunyikan dari ls biasa, bukan dari ls -a.", "ایک .cave_oubliee! نقطے نے اسے سادہ ls سے چھپایا، ls -a سے نہیں۔"),
 "hist.cit13.1.adulte": T("Énumérer = tout lister méthodiquement. Cacher par un point n'est pas une protection (« sécurité par l'obscurité »).", "Enumerating = methodically listing everything. Hiding with a dot isn't protection (“security through obscurity”).", "Enumerar = listar todo con método. Esconder con un punto no es protección («seguridad por oscuridad»).", "Aufzählen = methodisch alles auflisten. Mit einem Punkt verstecken ist kein Schutz („Security through Obscurity“).", "Enumerare = elencare tutto con metodo. Nascondere con un punto non è protezione («sicurezza tramite oscurità»).", "Enumerar = listar tudo com método. Esconder com um ponto não é proteção («segurança por obscuridade»).", "Перечисление — методично выписать всё. Спрятать точкой — не защита («безопасность через неясность»).", "枚举 = 有条理地把一切列出来。用点隐藏不算保护（“靠隐蔽求安全”）。", "列挙＝すべてを順序よく数え上げること。点でかくすのは守りではない（「隠ぺいによるセキュリティ」）。", "गिनती = सब कुछ तरीके से सूचीबद्ध करना। बिंदु से छिपाना सुरक्षा नहीं («छिपाकर सुरक्षा»)।", "التعداد = سرد كل شيء بمنهجية. الإخفاء بنقطة ليس حماية («الأمن بالإخفاء»).", "গণনা = নিয়ম মেনে সব তালিকা করা। বিন্দু দিয়ে লুকানো সুরক্ষা নয় («লুকিয়ে নিরাপত্তা»)।", "Enumerasi = mendaftar semuanya dengan teratur. Menyembunyikan dengan titik bukan perlindungan («keamanan lewat ketersembunyian»).", "شمار = سب کچھ ترتیب سے لکھنا۔ نقطے سے چھپانا حفاظت نہیں («چھپا کر حفاظت»)۔"),
 "hist.cit13.2.dit": T("Cherche les drapeaux TG{…} dans toute la boîte, même dans les recoins.", "Search the whole box for TG{…} flags, even in the corners.", "Busca las banderas TG{…} en toda la caja, incluso en los rincones.", "Suche die Flaggen TG{…} in der ganzen Kiste, auch in den Ecken.", "Cerca le bandiere TG{…} in tutta la scatola, anche negli angoli.", "Procure as bandeiras TG{…} em toda a caixa, até nos cantos.", "Найди флаги TG{…} по всей коробке, даже в закоулках.", "在整个盒子里找 TG{…} 旗帜，连角落也别放过。", "ボックス全体で TG{…} の旗をさがそう。すみっこも。", "पूरे बक्से में TG{…} झंडे ढूँढो, कोनों में भी।", "ابحث عن أعلام TG{…} في الصندوق كله، حتى الزوايا.", "পুরো বাক্সে TG{…} পতাকা খোঁজো, কোণেও।", "Cari bendera TG{…} di seluruh kotak, sampai ke sudut.", "پورے ڈبے میں TG{…} جھنڈے ڈھونڈو، کونوں میں بھی۔"),
 "hist.cit13.2.bravo": T("Deux drapeaux : l'entrée et le donjon, même dans .plus_profond !", "Two flags: entry and dungeon, even inside .plus_profond!", "Dos banderas: entrada y mazmorra, ¡incluso dentro de .plus_profond!", "Zwei Flaggen: Eingang und Verlies, sogar in .plus_profond!", "Due bandiere: ingresso e dongione, perfino in .plus_profond!", "Duas bandeiras: entrada e masmorra, até dentro de .plus_profond!", "Два флага: вход и донжон, даже в .plus_profond!", "两面旗：入口和地牢，连 .plus_profond 里都有！", "旗が2つ：入口と天守。.plus_profond の中まで！", "दो झंडे: प्रवेश और कालकोठरी, .plus_profond के अंदर भी!", "علمان: الدخول والبرج، حتى داخل .plus_profond!", "দুটো পতাকা: ঢোকা আর অন্ধকূপ, .plus_profond-এর ভেতরেও!", "Dua bendera: masuk dan ruang bawah, bahkan di dalam .plus_profond!", "دو جھنڈے: داخلہ اور تہہ خانہ، .plus_profond کے اندر بھی!"),
 "hist.cit13.2.adulte": T("grep -r cherche dans tous les fichiers des sous-dossiers, cachés compris. Les drapeaux changent à chaque partie (empreinte de ta graine).", "grep -r searches every file in subfolders, hidden ones included. The flags change each game (a hash of your seed).", "grep -r busca en todos los archivos de las subcarpetas, ocultos incluidos. Las banderas cambian en cada partida (huella de tu semilla).", "grep -r durchsucht alle Dateien der Unterordner, versteckte inklusive. Die Flaggen ändern sich je Partie (Hash deines Seeds).", "grep -r cerca in tutti i file delle sottocartelle, nascosti compresi. Le bandiere cambiano a ogni partita (impronta del tuo seme).", "grep -r procura em todos os arquivos das subpastas, ocultos inclusive. As bandeiras mudam a cada partida (hash da sua semente).", "grep -r ищет во всех файлах подпапок, включая скрытые. Флаги меняются в каждой партии (хеш твоего зерна).", "grep -r 会搜所有子文件夹里的文件，隐藏的也算。每局的旗都不一样（由你的种子算出的指纹）。", "grep -r はサブフォルダの全ファイルを、かくれたものもふくめてさがす。旗はゲームごとに変わる（きみのタネの指紋）。", "grep -r उप-फ़ोल्डरों की सारी फ़ाइलें खोजता है, छिपी भी। झंडे हर खेल में बदलते हैं (तुम्हारे बीज का हैश)।", "يبحث grep -r في كل ملفات المجلدات الفرعية، بما فيها المخفية. تتغير الأعلام في كل لعبة (بصمة بذرتك).", "grep -r সব সাব-ফোল্ডারের সব ফাইলে খোঁজে, লুকানোসহ। প্রতি খেলায় পতাকা বদলায় (তোমার বীজের হ্যাশ)।", "grep -r mencari di semua berkas subfolder, termasuk yang tersembunyi. Benderanya berubah tiap permainan (hash benihmu).", "grep -r ذیلی فولڈروں کی ساری فائلیں ڈھونڈتا ہے، چھپی بھی۔ جھنڈے ہر کھیل میں بدلتے ہیں (تمہارے بیج کا ہیش)۔"),
 "hist.cit13.3.dit": T("Rends les drapeaux, un par un (remplace ? par un drapeau entier, TG{…} compris).", "Hand in the flags, one by one (replace ? with a whole flag, TG{…} included).", "Entrega las banderas, una a una (cambia ? por una bandera entera, con TG{…}).", "Gib die Flaggen ab, eine nach der anderen (ersetze ? durch eine ganze Flagge, mit TG{…}).", "Consegna le bandiere, una alla volta (sostituisci ? con una bandiera intera, TG{…} compreso).", "Entregue as bandeiras, uma por uma (troque ? por uma bandeira inteira, com TG{…}).", "Сдай флаги по одному (замени ? на флаг целиком, вместе с TG{…}).", "一面一面交旗（把 ? 换成完整的旗，包括 TG{…}）。", "旗をひとつずつ出そう（? を TG{…} までふくめた旗まるごとに変えて）。", "झंडे एक-एक कर जमा करो (? की जगह पूरा झंडा, TG{…} समेत)।", "سلّم الأعلام واحدًا واحدًا (استبدل ? بعلم كامل بما فيه TG{…}).", "পতাকাগুলো একটা একটা জমা দাও (? এর জায়গায় পুরো পতাকা, TG{…} সহ)।", "Serahkan bendera satu per satu (ganti ? dengan bendera utuh, termasuk TG{…}).", "جھنڈے ایک ایک کر کے جمع کرو (? کی جگہ پورا جھنڈا، TG{…} سمیت)۔"),
 "hist.cit13.3.bravo": T("Manche Enquête gagnée ! Maintenant, la manche Rempart : répare la faiblesse.", "Investigation round won! Now the Rampart round: fix the weakness.", "¡Ronda de investigación ganada! Ahora la ronda Muralla: repara la debilidad.", "Ermittlungsrunde gewonnen! Jetzt die Wall-Runde: Behebe die Schwachstelle.", "Manche Indagine vinta! Ora la manche Bastione: ripara la debolezza.", "Rodada Investigação vencida! Agora a rodada Muralha: conserte a falha.", "Раунд расследования выигран! Теперь раунд стены: исправь слабое место.", "调查回合赢了！现在是城墙回合：把弱点修好。", "調査ラウンドの勝ち！つぎは城壁ラウンド：弱点を直そう。", "जाँच का दौर जीत लिया! अब प्राचीर का दौर: कमज़ोरी ठीक करो।", "فزت بجولة التحقيق! الآن جولة السور: أصلح الثغرة.", "তদন্ত দফা জিতেছ! এবার প্রাচীর দফা: দুর্বলতা সারাও।", "Babak Penyelidikan menang! Sekarang babak Benteng: perbaiki kelemahannya.", "تفتیش کا دور جیت لیا! اب فصیل کا دور: کمزوری ٹھیک کرو۔"),
 "hist.cit13.3.adulte": T("Un drapeau n'est qu'une preuve qu'on a atteint un endroit. Le vrai but d'un défenseur, c'est la deuxième manche : corriger.", "A flag is only proof you reached a place. A defender's real goal is the second round: fixing.", "Una bandera solo prueba que se llegó a un lugar. El verdadero objetivo de un defensor es la segunda ronda: corregir.", "Eine Flagge beweist nur, dass man einen Ort erreicht hat. Das echte Ziel eines Verteidigers ist die zweite Runde: beheben.", "Una bandiera è solo la prova di aver raggiunto un posto. Il vero obiettivo di un difensore è la seconda manche: correggere.", "Uma bandeira só prova que se chegou a um lugar. O objetivo real de um defensor é a segunda rodada: corrigir.", "Флаг лишь доказывает, что ты добрался до места. Настоящая цель защитника — второй раунд: исправить.", "旗只能证明你到过某个地方。防守者真正的目标是第二回合：修好。", "旗は、その場所に着いたしるしにすぎない。守る人の本当の目的は第2ラウンド：直すこと。", "झंडा सिर्फ़ इस बात का सबूत है कि तुम कहीं पहुँचे। रक्षक का असली लक्ष्य दूसरा दौर है: सुधारना।", "العلم مجرد دليل على أنك وصلت إلى مكان. الهدف الحقيقي للمدافع هو الجولة الثانية: الإصلاح.", "পতাকা শুধু প্রমাণ যে তুমি কোথাও পৌঁছেছ। রক্ষীর আসল লক্ষ্য দ্বিতীয় দফা: সারানো।", "Bendera hanya bukti kamu sampai di suatu tempat. Tujuan sejati pembela adalah babak kedua: memperbaiki.", "جھنڈا صرف ثبوت ہے کہ تم کہیں پہنچے۔ محافظ کا اصل مقصد دوسرا دور ہے: ٹھیک کرنا۔"),
 "hist.cit13.4.dit": T("Rempart : la cave est ouverte à tous (r-x pour les autres). Ferme-la aux autres (o = les autres, - = enlever, rwx = tout).", "Rampart: the cellar is open to everyone (r-x for others). Close it to the others (o = others, - = remove, rwx = everything).", "Muralla: el sótano está abierto a todos (r-x para los demás). Ciérralo a los demás (o = los demás, - = quitar, rwx = todo).", "Wall: Der Keller ist für alle offen (r-x für andere). Schließ ihn für die anderen (o = andere, - = wegnehmen, rwx = alles).", "Bastione: la cantina è aperta a tutti (r-x per gli altri). Chiudila agli altri (o = gli altri, - = togliere, rwx = tutto).", "Muralha: o porão está aberto a todos (r-x para os outros). Feche para os outros (o = os outros, - = tirar, rwx = tudo).", "Стена: подвал открыт всем (r-x для остальных). Закрой его для остальных (o — остальные, - — убрать, rwx — всё).", "城墙：地窖对所有人开着（其他人是 r-x）。对其他人关上（o = 其他人，- = 拿掉，rwx = 全部）。", "城壁：地下室がみんなに開いている（その他は r-x）。その他に閉じよう（o＝その他、-＝取る、rwx＝全部）。", "प्राचीर: तहखाना सबके लिए खुला है (बाकी के लिए r-x)। बाकी के लिए बंद करो (o = बाकी, - = हटाना, rwx = सब)।", "السور: القبو مفتوح للجميع (r-x للآخرين). أغلقه أمام الآخرين (o الآخرون، - إزالة، rwx الكل).", "প্রাচীর: মাটির ঘর সবার জন্য খোলা (অন্যদের r-x)। অন্যদের জন্য বন্ধ করো (o = অন্যরা, - = সরানো, rwx = সব)।", "Benteng: ruang bawah terbuka untuk semua (r-x untuk lainnya). Tutup untuk yang lain (o = lainnya, - = cabut, rwx = semua).", "فصیل: تہہ خانہ سب کے لیے کھلا ہے (باقی کے لیے r-x)۔ باقی کے لیے بند کرو (o = باقی، - = ہٹانا، rwx = سب)۔"),
 "hist.cit13.4.bravo": T("Caché ET fermé : maintenant, la cave est vraiment protégée.", "Hidden AND locked: now the cellar is really protected.", "Oculto Y cerrado: ahora el sótano está protegido de verdad.", "Versteckt UND verschlossen: Jetzt ist der Keller wirklich geschützt.", "Nascosta E chiusa: ora la cantina è davvero protetta.", "Escondido E trancado: agora o porão está protegido de verdade.", "Спрятан И заперт: теперь подвал по-настоящему защищён.", "既藏好又锁上：现在地窖真的安全了。", "かくして、しかも閉めた：いまは本当に守られている。", "छिपा और बंद: अब तहखाना सच में सुरक्षित है।", "مخفي ومغلق: الآن القبو محمي حقًا.", "লুকানো আর বন্ধ: এবার মাটির ঘর সত্যিই সুরক্ষিত।", "Tersembunyi DAN terkunci: kini ruang bawah benar-benar terlindungi.", "چھپا اور بند: اب تہہ خانہ واقعی محفوظ ہے۔"),
 "hist.cit13.4.adulte": T("Sur un dossier, r = lister, x = traverser. Sans r ni x pour « o », les autres ne peuvent ni voir dedans ni y entrer.", "On a folder, r = list, x = go through. Without r or x for “o”, the others can neither see inside nor enter.", "En una carpeta, r = listar, x = atravesar. Sin r ni x para «o», los demás no pueden ver dentro ni entrar.", "Bei einem Ordner: r = auflisten, x = durchgehen. Ohne r und x für „o“ können andere weder hineinsehen noch hinein.", "Su una cartella, r = elencare, x = attraversare. Senza r né x per «o», gli altri non possono vedere dentro né entrare.", "Numa pasta, r = listar, x = atravessar. Sem r nem x para «o», os outros não podem ver dentro nem entrar.", "У папки r — показать список, x — пройти внутрь. Без r и x для «o» остальные не видят содержимое и не могут войти.", "对文件夹来说，r = 列出，x = 进入。o 没有 r 也没有 x，其他人既看不见里面，也进不去。", "フォルダでは r＝一覧を見る、x＝通る。o に r も x もなければ、その他の人は中を見ることも入ることもできない。", "फ़ोल्डर पर r = सूची देखना, x = अंदर जाना। «o» के लिए न r न x, तो बाकी न अंदर देख सकते न जा सकते।", "على المجلد: r للسرد، x للعبور. بدون r ولا x لـ «o» لا يستطيع الآخرون الرؤية في الداخل ولا الدخول.", "ফোল্ডারে r = তালিকা দেখা, x = ভেতরে যাওয়া। «o»-এর r আর x না থাকলে অন্যরা ভেতরে দেখতেও পারে না, ঢুকতেও না।", "Pada folder, r = melihat isi, x = masuk. Tanpa r dan x untuk «o», yang lain tak bisa melihat atau masuk.", "فولڈر پر r = فہرست دیکھنا، x = اندر جانا۔ «o» کے لیے نہ r نہ x، تو باقی نہ اندر دیکھ سکتے نہ جا سکتے۔"),
 "hist.cit13.5.dit": T("Appelle l'inspecteur : il rejoue l'attaque pour vérifier ta réparation.", "Call the inspector: he replays the attack to check your repair.", "Llama al inspector: repite el ataque para comprobar tu reparación.", "Ruf den Inspektor: Er wiederholt den Angriff, um deine Reparatur zu prüfen.", "Chiama l'ispettore: rigioca l'attacco per verificare la tua riparazione.", "Chame o inspetor: ele repete o ataque para conferir seu conserto.", "Позови инспектора: он повторит атаку и проверит починку.", "叫检查员来：他会重放攻击，检查你的修补。", "検査官を呼ぼう：攻撃をやりなおして、修理を確かめる。", "निरीक्षक को बुलाओ: वह हमला दोहराकर तुम्हारी मरम्मत जाँचेगा।", "استدعِ المفتش: سيعيد الهجوم ليتحقق من إصلاحك.", "পরিদর্শককে ডাকো: সে আক্রমণ আবার চালিয়ে মেরামত যাচাই করবে।", "Panggil inspektur: ia mengulang serangan untuk memeriksa perbaikanmu.", "انسپکٹر کو بلاؤ: وہ حملہ دہرا کر تمہاری مرمت جانچے گا۔"),
 "hist.cit13.5.bravo": T("Boîte maîtrisée, deux manches ! Une créature-gardienne « glitch » viendra peut-être te voir…", "Box mastered, both rounds! A “glitch” guardian creature may come to visit…", "¡Caja dominada, dos rondas! Quizá una criatura guardiana «glitch» venga a verte…", "Kiste gemeistert, beide Runden! Vielleicht besucht dich eine „Glitch“-Wächterkreatur …", "Scatola padroneggiata, due manche! Forse una creatura guardiana «glitch» verrà a trovarti…", "Caixa dominada, duas rodadas! Talvez uma criatura guardiã «glitch» venha te ver…", "Коробка освоена, оба раунда! Возможно, к тебе заглянет существо-страж «глитч»…", "盒子拿下，两回合全胜！也许会有一只“故障”守护生物来找你……", "ボックス制覇、2ラウンドとも！「グリッチ」の守り手の生き物が会いに来るかも……", "बक्सा जीत लिया, दोनों दौर! शायद कोई «ग्लिच» रक्षक जीव तुमसे मिलने आए…", "أتقنت الصندوق بجولتيه! ربما يزورك مخلوق حارس «خلل»…", "বাক্স আয়ত্তে, দুই দফাই! হয়তো একটা «গ্লিচ» রক্ষী প্রাণী দেখা করতে আসবে…", "Kotak dikuasai, dua babak! Mungkin makhluk penjaga «glitch» akan datang…", "ڈبہ قابو میں، دونوں دور! شاید کوئی «گلچ» محافظ جانور ملنے آئے…"),
 "hist.cit13.5.adulte": T("L'inspecteur lit les vrais droits (stat) de la boîte : la correction est vérifiée, pas seulement déclarée.", "The inspector reads the box's real permissions (stat): the fix is checked, not just claimed.", "El inspector lee los permisos reales (stat) de la caja: la corrección se verifica, no solo se declara.", "Der Inspektor liest die echten Rechte (stat) der Kiste: Die Korrektur wird geprüft, nicht nur behauptet.", "L'ispettore legge i veri permessi (stat) della scatola: la correzione è verificata, non solo dichiarata.", "O inspetor lê as permissões reais (stat) da caixa: a correção é conferida, não só declarada.", "Инспектор читает настоящие права (stat) коробки: исправление проверено, а не просто заявлено.", "检查员会读盒子真实的权限（stat）：修补要经过验证，光说不算。", "検査官はボックスの本当の権限（stat）を読む：直したと言うだけでなく、確かめられる。", "निरीक्षक बक्से के असली अधिकार (stat) पढ़ता है: सुधार जाँचा जाता है, सिर्फ़ कहा नहीं जाता।", "يقرأ المفتش الصلاحيات الحقيقية (stat) للصندوق: يُتحقق من الإصلاح لا يُدّعى فقط.", "পরিদর্শক বাক্সের আসল অধিকার (stat) পড়ে: সারানোটা যাচাই হয়, শুধু বলা হয় না।", "Inspektur membaca izin sebenarnya (stat) kotak: perbaikan diperiksa, bukan sekadar diklaim.", "انسپکٹر ڈبے کے اصل حقوق (stat) پڑھتا ہے: درستی جانچی جاتی ہے، صرف کہی نہیں جاتی۔"),
 # ------------------------------------------------------------------ cit14 boîte Droits mal réglés
 "hist.cit14.0.dit": T("Boîte « Les droits mal réglés » : lis les cadenas de chaque fichier.", "Box “The badly set permissions”: read every file's locks.", "Caja «Los permisos mal puestos»: lee los candados de cada archivo.", "Kiste „Die falsch gesetzten Rechte“: Lies die Schlösser jeder Datei.", "Scatola «I permessi sbagliati»: leggi i lucchetti di ogni file.", "Caixa «As permissões mal ajustadas»: leia os cadeados de cada arquivo.", "Коробка «Неверные права»: прочитай замки каждого файла.", "盒子“设错的权限”：读一读每个文件的锁。", "ボックス「まちがった権限」：それぞれのファイルの錠前を読もう。", "बक्सा «गलत अनुमतियाँ»: हर फ़ाइल के ताले पढ़ो।", "صندوق «الأذونات المضبوطة خطأً»: اقرأ أقفال كل ملف.", "বাক্স «ভুল অনুমতি»: প্রতিটা ফাইলের তালা পড়ো।", "Kotak «Izin yang salah atur»: baca gembok tiap berkas.", "ڈبہ «غلط اجازتیں»: ہر فائل کے تالے پڑھو۔"),
 "hist.cit14.0.bravo": T("journal_secret.txt lisible par tous, et ronde.sh avec un w pour les autres (rwxr-xrwx). Aïe !", "journal_secret.txt readable by all, and ronde.sh with a w for others (rwxr-xrwx). Ouch!", "journal_secret.txt legible por todos, y ronde.sh con una w para los demás (rwxr-xrwx). ¡Ay!", "journal_secret.txt für alle lesbar, und ronde.sh mit w für andere (rwxr-xrwx). Autsch!", "journal_secret.txt leggibile da tutti, e ronde.sh con una w per gli altri (rwxr-xrwx). Ahi!", "journal_secret.txt legível por todos, e ronde.sh com w para os outros (rwxr-xrwx). Ai!", "journal_secret.txt читают все, а у ronde.sh есть w для остальных (rwxr-xrwx). Ой!", "journal_secret.txt 谁都能读，ronde.sh 对其他人有 w（rwxr-xrwx）。哎呀！", "journal_secret.txt はだれでも読めて、ronde.sh にはその他の w がある（rwxr-xrwx）。いたた！", "journal_secret.txt सब पढ़ सकते हैं, और ronde.sh पर बाकी के लिए w है (rwxr-xrwx)। आह!", "journal_secret.txt يقرؤه الجميع، وronde.sh فيه w للآخرين (rwxr-xrwx). آه!", "journal_secret.txt সবাই পড়তে পারে, আর ronde.sh-এ অন্যদের w আছে (rwxr-xrwx)। উফ!", "journal_secret.txt bisa dibaca semua, dan ronde.sh punya w untuk lainnya (rwxr-xrwx). Aduh!", "journal_secret.txt سب پڑھ سکتے ہیں، اور ronde.sh پر باقی کے لیے w ہے (rwxr-xrwx)۔ اف!"),
 "hist.cit14.0.adulte": T("Un script modifiable par tous mais lancé par le gardien : n'importe qui pourrait y glisser ses propres ordres. C'est une vraie faiblesse courante.", "A script anyone can edit but the guardian runs: anyone could slip their own orders into it. It's a real, common weakness.", "Un script que todos pueden modificar pero que ejecuta el guardián: cualquiera podría meter sus propias órdenes. Es una debilidad real y frecuente.", "Ein Skript, das jeder ändern kann, aber der Wächter startet: Jeder könnte eigene Befehle einschmuggeln. Eine echte, häufige Schwachstelle.", "Uno script modificabile da tutti ma lanciato dal guardiano: chiunque potrebbe infilarci i propri ordini. È una debolezza reale e comune.", "Um script que todos podem mudar mas que o guardião executa: qualquer um poderia enfiar ordens próprias. É uma falha real e comum.", "Скрипт, который может менять любой, а запускает страж: кто угодно подсунет туда свои команды. Это настоящая и частая уязвимость.", "人人都能改、却由守卫来运行的脚本：谁都能往里塞自己的命令。这是真实又常见的弱点。", "だれでも書きかえられるのに守り手が実行するスクリプト：だれでも自分の命令をしのびこませられる。本当によくある弱点。", "ऐसी स्क्रिप्ट जिसे कोई भी बदल सके पर चलाए रक्षक: कोई भी अपने आदेश घुसा सकता है। यह असली और आम कमज़ोरी है।", "سكربت يعدّله أي أحد لكن يشغّله الحارس: يستطيع أي شخص دسّ أوامره فيه. ثغرة حقيقية وشائعة.", "যে স্ক্রিপ্ট যে কেউ বদলাতে পারে কিন্তু রক্ষী চালায়: যে কেউ নিজের আদেশ ঢুকিয়ে দিতে পারে। এটা সত্যিকারের, সাধারণ দুর্বলতা।", "Skrip yang bisa diubah siapa saja tapi dijalankan penjaga: siapa pun bisa menyelipkan perintahnya. Ini kelemahan nyata dan umum.", "ایسا اسکرپٹ جسے کوئی بھی بدل سکے مگر محافظ چلائے: کوئی بھی اپنے حکم گھسا سکتا ہے۔ یہ اصل اور عام کمزوری ہے۔"),
 "hist.cit14.1.dit": T("Trouve automatiquement tout ce que « les autres » peuvent modifier.", "Automatically find everything “the others” can change.", "Encuentra automáticamente todo lo que «los demás» pueden cambiar.", "Finde automatisch alles, was „die anderen“ ändern können.", "Trova automaticamente tutto ciò che «gli altri» possono modificare.", "Ache automaticamente tudo o que «os outros» podem mudar.", "Найди автоматически всё, что могут менять «остальные».", "自动找出“其他人”能改的所有东西。", "「その他」が書きかえられるものを全部、自動で見つけよう。", "अपने-आप वह सब ढूँढो जो «बाकी» बदल सकते हैं।", "اعثر تلقائيًا على كل ما يستطيع «الآخرون» تعديله.", "«অন্যরা» বদলাতে পারে এমন সব আপনা থেকে খুঁজে বের করো।", "Temukan otomatis semua yang bisa diubah «yang lain».", "خود بخود وہ سب ڈھونڈو جو «باقی» بدل سکتے ہیں۔"),
 "hist.cit14.1.bravo": T("ronde.sh : le seul fichier modifiable par n'importe qui. Les défenseurs lancent cette recherche sur des serveurs entiers.", "ronde.sh: the only file anyone can change. Defenders run this search across whole servers.", "ronde.sh: el único archivo que cualquiera puede cambiar. Los defensores lanzan esta búsqueda en servidores enteros.", "ronde.sh: die einzige Datei, die jeder ändern kann. Verteidiger lassen diese Suche über ganze Server laufen.", "ronde.sh: l'unico file modificabile da chiunque. I difensori lanciano questa ricerca su server interi.", "ronde.sh: o único arquivo que qualquer um pode mudar. Os defensores rodam essa busca em servidores inteiros.", "ronde.sh — единственный файл, который может изменить кто угодно. Защитники запускают такой поиск по целым серверам.", "ronde.sh：唯一谁都能改的文件。防守的人会在整台服务器上跑这种搜索。", "ronde.sh：だれでも書きかえられる、ただひとつのファイル。守る人たちはサーバー全体でこの検索をする。", "ronde.sh: अकेली फ़ाइल जिसे कोई भी बदल सकता है। रक्षक पूरे सर्वरों पर यह खोज चलाते हैं।", "ronde.sh: الملف الوحيد الذي يعدّله أي أحد. يشغّل المدافعون هذا البحث على خوادم كاملة.", "ronde.sh: একমাত্র ফাইল যা যে কেউ বদলাতে পারে। রক্ষীরা পুরো সার্ভারে এই খোঁজ চালায়।", "ronde.sh: satu-satunya berkas yang bisa diubah siapa saja. Para pembela menjalankan pencarian ini di seluruh server.", "ronde.sh: اکیلی فائل جسے کوئی بھی بدل سکتا ہے۔ محافظ پورے سرورز پر یہ تلاش چلاتے ہیں۔"),
 "hist.cit14.1.adulte": T("find -perm -o+w : les fichiers dont au moins le bit w des « autres » est mis. Variante : -perm -o+r pour ce qui est lisible par tous.", "find -perm -o+w: files with at least the “others” w bit set. Variant: -perm -o+r for world-readable files.", "find -perm -o+w: archivos con al menos el bit w de «otros». Variante: -perm -o+r para lo legible por todos.", "find -perm -o+w: Dateien, bei denen mindestens das w-Bit der „anderen“ gesetzt ist. Variante: -perm -o+r für für alle Lesbares.", "find -perm -o+w: i file con almeno il bit w degli «altri». Variante: -perm -o+r per ciò che è leggibile da tutti.", "find -perm -o+w: arquivos com pelo menos o bit w dos «outros». Variante: -perm -o+r para o que é legível por todos.", "find -perm -o+w: файлы, где установлен хотя бы бит w у «остальных». Вариант: -perm -o+r для читаемого всеми.", "find -perm -o+w：至少设了“其他人” w 位的文件。变体：-perm -o+r 找谁都能读的。", "find -perm -o+w：少なくとも「その他」の w が立っているファイル。-perm -o+r ならだれでも読めるもの。", "find -perm -o+w: वे फ़ाइलें जिनमें कम से कम «बाकी» का w बिट लगा है। विकल्प: -perm -o+r सबके पढ़ने लायक के लिए।", "find -perm -o+w: الملفات التي فيها بت w للآخرين على الأقل. بديل: -perm -o+r لما يقرؤه الجميع.", "find -perm -o+w: যেসব ফাইলে অন্তত «অন্যদের» w বিট আছে। বিকল্প: -perm -o+r সবার পড়ার মতো ফাইলের জন্য।", "find -perm -o+w: berkas yang setidaknya bit w «lainnya» menyala. Varian: -perm -o+r untuk yang bisa dibaca semua.", "find -perm -o+w: وہ فائلیں جن میں کم از کم «باقی» کا w بٹ لگا ہے۔ متبادل: -perm -o+r سب کے پڑھنے لائق کے لیے۔"),
 "hist.cit14.2.dit": T("Trouve les drapeaux de cette boîte.", "Find this box's flags.", "Encuentra las banderas de esta caja.", "Finde die Flaggen dieser Kiste.", "Trova le bandiere di questa scatola.", "Ache as bandeiras desta caixa.", "Найди флаги этой коробки.", "找出这个盒子的旗。", "このボックスの旗を見つけよう。", "इस बक्से के झंडे ढूँढो।", "اعثر على أعلام هذا الصندوق.", "এই বাক্সের পতাকা খোঁজো।", "Temukan bendera kotak ini.", "اس ڈبے کے جھنڈے ڈھونڈو۔"),
 "hist.cit14.2.bravo": T("L'entrée dans le journal, le donjon dans la ronde. Tout ce qui est mal fermé se lit.", "Entry in the diary, dungeon in the patrol script. Anything badly locked can be read.", "La entrada en el diario, la mazmorra en la ronda. Todo lo mal cerrado se lee.", "Eingang im Tagebuch, Verlies im Rundenskript. Alles schlecht Verschlossene ist lesbar.", "L'ingresso nel diario, il dongione nella ronda. Tutto ciò che è chiuso male si legge.", "A entrada no diário, a masmorra na ronda. Tudo que está mal trancado se lê.", "Вход — в дневнике, донжон — в скрипте обхода. Всё плохо запертое читается.", "入口旗在日记里，地牢旗在巡逻脚本里。锁不好的东西都能被读到。", "入口の旗は日記に、天守の旗は見回りスクリプトに。しっかり閉めていないものは読まれる。", "प्रवेश डायरी में, कालकोठरी गश्त में। जो ठीक से बंद नहीं, वह पढ़ा जाता है।", "الدخول في المذكرات، والبرج في الجولة. كل ما أُغلق خطأً يُقرأ.", "ঢোকার পতাকা ডায়েরিতে, অন্ধকূপেরটা টহলে। ঠিকমতো বন্ধ না থাকলে সব পড়া যায়।", "Masuk di buku harian, ruang bawah di skrip patroli. Yang salah kunci bisa dibaca.", "داخلہ ڈائری میں، تہہ خانہ گشت میں۔ جو ٹھیک سے بند نہیں وہ پڑھا جاتا ہے۔"),
 "hist.cit14.2.adulte": T("Dans un vrai audit, un fichier lisible qui contient un secret est déjà une fuite, même si personne ne l'a encore lu.", "In a real audit, a readable file holding a secret is already a leak, even if nobody has read it yet.", "En una auditoría real, un archivo legible con un secreto ya es una fuga, aunque nadie lo haya leído aún.", "In einem echten Audit ist eine lesbare Datei mit Geheimnis bereits ein Leck, auch wenn sie noch niemand gelesen hat.", "In un vero audit, un file leggibile che contiene un segreto è già una fuga, anche se nessuno l'ha ancora letto.", "Numa auditoria real, um arquivo legível com um segredo já é um vazamento, mesmo que ninguém tenha lido.", "При настоящей проверке читаемый файл с секретом — уже утечка, даже если его ещё никто не прочёл.", "真正的检查中，能被读到又含秘密的文件，就已经算泄露了，哪怕还没人读过。", "本当の点検では、秘密が入った読めるファイルは、まだだれも読んでいなくても、もう「もれ」とみなされる。", "असली जाँच में राज़ वाली पढ़ने लायक फ़ाइल पहले से ही रिसाव है, भले अभी किसी ने न पढ़ी हो।", "في التدقيق الحقيقي، الملف المقروء الذي يحوي سرًا هو تسريب بالفعل، ولو لم يقرأه أحد بعد.", "আসল নিরীক্ষায় গোপন কথাওয়ালা পড়ার মতো ফাইল আগেই ফাঁস, কেউ না পড়লেও।", "Dalam audit sungguhan, berkas terbaca yang berisi rahasia sudah merupakan kebocoran, walau belum ada yang membacanya.", "اصل جانچ میں راز والی پڑھنے لائق فائل پہلے ہی رساؤ ہے، چاہے ابھی کسی نے نہ پڑھی ہو۔"),
 "hist.cit14.3.dit": T("Rends les deux drapeaux (remplace ? par un drapeau, une fois chacun).", "Hand in both flags (replace ? with a flag, once each).", "Entrega las dos banderas (cambia ? por una bandera, una vez cada una).", "Gib beide Flaggen ab (ersetze ? durch eine Flagge, je einmal).", "Consegna le due bandiere (sostituisci ? con una bandiera, una volta ciascuna).", "Entregue as duas bandeiras (troque ? por uma bandeira, uma vez cada).", "Сдай оба флага (замени ? на флаг, по разу на каждый).", "交上两面旗（把 ? 换成旗，每面交一次）。", "旗を2つとも出そう（? を旗に変えて、1つずつ）。", "दोनों झंडे जमा करो (? की जगह झंडा, एक-एक बार)।", "سلّم العلمين (استبدل ? بعلم، مرة لكل واحد).", "দুটো পতাকাই জমা দাও (? এর জায়গায় পতাকা, একটা করে)।", "Serahkan kedua bendera (ganti ? dengan bendera, sekali masing-masing).", "دونوں جھنڈے جمع کرو (? کی جگہ جھنڈا، ایک ایک بار)۔"),
 "hist.cit14.3.bravo": T("Enquête finie. Place au moindre privilège : chacun n'a que les clés dont il a besoin.", "Investigation done. Now least privilege: everyone gets only the keys they need.", "Investigación terminada. Ahora el mínimo privilegio: cada uno solo tiene las llaves que necesita.", "Ermittlung fertig. Jetzt das Prinzip der geringsten Rechte: Jeder bekommt nur die Schlüssel, die er braucht.", "Indagine finita. Ora il minimo privilegio: ognuno ha solo le chiavi di cui ha bisogno.", "Investigação concluída. Agora o menor privilégio: cada um só tem as chaves de que precisa.", "Расследование окончено. Теперь минимальные права: у каждого только нужные ключи.", "调查结束。现在讲最小权限：每个人只拿需要的钥匙。", "調査おわり。つぎは最小権限：それぞれ必要な鍵だけを持つ。", "जाँच पूरी। अब न्यूनतम अधिकार: हर किसी के पास बस ज़रूरी चाबियाँ।", "انتهى التحقيق. الآن مبدأ الحد الأدنى من الصلاحيات: لكلٍّ المفاتيح التي يحتاجها فقط.", "তদন্ত শেষ। এবার ন্যূনতম অধিকার: প্রত্যেকের কাছে শুধু দরকারি চাবি।", "Penyelidikan selesai. Kini hak minimum: tiap orang hanya memegang kunci yang dibutuhkan.", "تفتیش ختم۔ اب کم سے کم اختیار: ہر کسی کے پاس صرف ضروری چابیاں۔"),
 "hist.cit14.3.adulte": T("Principe du moindre privilège : donner le minimum de droits nécessaires, à chaque compte et chaque fichier.", "Principle of least privilege: give the minimum necessary rights to every account and every file.", "Principio de mínimo privilegio: dar los derechos mínimos necesarios a cada cuenta y cada archivo.", "Prinzip der geringsten Rechte: jedem Konto und jeder Datei nur die nötigsten Rechte geben.", "Principio del minimo privilegio: dare i diritti minimi necessari a ogni account e ogni file.", "Princípio do menor privilégio: dar o mínimo de direitos necessários a cada conta e cada arquivo.", "Принцип минимальных прав: давать каждой учётной записи и каждому файлу только необходимое.", "最小权限原则：给每个账号、每个文件只开必要的最少权限。", "最小権限の原則：どのアカウントにもファイルにも、必要な最小限の権限だけをあたえる。", "न्यूनतम अधिकार का सिद्धांत: हर खाते और हर फ़ाइल को बस ज़रूरी अधिकार दो।", "مبدأ الحد الأدنى من الصلاحيات: إعطاء أقل الحقوق اللازمة لكل حساب وكل ملف.", "ন্যূনতম অধিকারের নীতি: প্রতিটা অ্যাকাউন্ট আর ফাইলকে দরকারি ন্যূনতম অধিকার দাও।", "Prinsip hak minimum: beri hak paling sedikit yang perlu ke setiap akun dan berkas.", "کم سے کم اختیار کا اصول: ہر اکاؤنٹ اور ہر فائل کو صرف ضروری حقوق دو۔"),
 "hist.cit14.4.dit": T("Rempart : enlève tous les droits des « autres » sur les fichiers de la boîte.", "Rampart: remove all of “others'” rights on the box's files.", "Muralla: quita todos los derechos de «los demás» sobre los archivos de la caja.", "Wall: Nimm „den anderen“ alle Rechte an den Dateien der Kiste.", "Bastione: togli tutti i diritti degli «altri» sui file della scatola.", "Muralha: tire todos os direitos dos «outros» sobre os arquivos da caixa.", "Стена: убери у «остальных» все права на файлы коробки.", "城墙：拿掉“其他人”对盒子里所有文件的全部权限。", "城壁：ボックスのファイルから「その他」の権限を全部取ろう。", "प्राचीर: बक्से की फ़ाइलों पर «बाकी» के सारे अधिकार हटाओ।", "السور: أزل كل حقوق «الآخرين» على ملفات الصندوق.", "প্রাচীর: বাক্সের ফাইলে «অন্যদের» সব অধিকার সরাও।", "Benteng: cabut semua hak «yang lain» atas berkas kotak.", "فصیل: ڈبے کی فائلوں پر «باقی» کے سارے حقوق ہٹاؤ۔"),
 "hist.cit14.4.bravo": T("Plus rien pour les autres : ni lire le journal, ni toucher la ronde.", "Nothing left for others: they can't read the diary or touch the patrol.", "Nada para los demás: ni leer el diario ni tocar la ronda.", "Nichts mehr für andere: weder Tagebuch lesen noch Runde ändern.", "Niente più per gli altri: né leggere il diario né toccare la ronda.", "Nada para os outros: nem ler o diário nem mexer na ronda.", "Остальным ничего: ни читать дневник, ни трогать обход.", "其他人什么都做不了：读不了日记，也碰不了巡逻脚本。", "その他の人には何もできない：日記も読めず、見回りもさわれない。", "बाकी के लिए कुछ नहीं: न डायरी पढ़ सकते, न गश्त छू सकते।", "لا شيء للآخرين: لا قراءة المذكرات ولا لمس الجولة.", "অন্যদের জন্য আর কিছু নেই: না ডায়েরি পড়া, না টহল ছোঁয়া।", "Tak ada lagi untuk yang lain: tak bisa membaca buku harian atau menyentuh patroli.", "باقی کے لیے کچھ نہیں: نہ ڈائری پڑھ سکتے، نہ گشت چھو سکتے۔"),
 "hist.cit14.4.adulte": T("Le joker * désigne tous les fichiers visibles du dossier ; chmod les traite un par un.", "The * wildcard means every visible file in the folder; chmod handles them one by one.", "El comodín * designa todos los archivos visibles de la carpeta; chmod los trata uno a uno.", "Der Platzhalter * steht für alle sichtbaren Dateien im Ordner; chmod behandelt sie einzeln.", "Il jolly * indica tutti i file visibili della cartella; chmod li tratta uno per uno.", "O curinga * indica todos os arquivos visíveis da pasta; o chmod trata um por um.", "Шаблон * обозначает все видимые файлы папки; chmod обрабатывает их по очереди.", "通配符 * 代表文件夹里所有看得见的文件；chmod 会一个个处理。", "ワイルドカード * はフォルダの見えるファイル全部。chmod はひとつずつ処理する。", "जोकर * फ़ोल्डर की सारी दिखने वाली फ़ाइलें है; chmod एक-एक कर बदलता है।", "الرمز * يعني كل الملفات الظاهرة في المجلد؛ ويعالجها chmod واحدًا واحدًا.", "জোকার * ফোল্ডারের সব দৃশ্যমান ফাইল বোঝায়; chmod একটা একটা করে বদলায়।", "Joker * berarti semua berkas terlihat di folder; chmod mengubahnya satu per satu.", "جوکر * فولڈر کی ساری نظر آنے والی فائلیں ہے؛ chmod ایک ایک کر کے بدلتا ہے۔"),
 "hist.cit14.5.dit": T("Appelle l'inspecteur pour la boîte des droits.", "Call the inspector for the permissions box.", "Llama al inspector para la caja de permisos.", "Ruf den Inspektor für die Rechte-Kiste.", "Chiama l'ispettore per la scatola dei permessi.", "Chame o inspetor para a caixa das permissões.", "Позови инспектора для коробки прав.", "叫检查员来查权限盒子。", "権限のボックスに検査官を呼ぼう。", "अनुमतियों वाले बक्से के लिए निरीक्षक बुलाओ।", "استدعِ المفتش لصندوق الأذونات.", "অনুমতির বাক্সের জন্য পরিদর্শক ডাকো।", "Panggil inspektur untuk kotak izin.", "اجازتوں والے ڈبے کے لیے انسپکٹر بلاؤ۔"),
 "hist.cit14.5.bravo": T("Deuxième boîte maîtrisée ! Tu penses comme un défenseur.", "Second box mastered! You think like a defender.", "¡Segunda caja dominada! Piensas como un defensor.", "Zweite Kiste gemeistert! Du denkst wie ein Verteidiger.", "Seconda scatola padroneggiata! Pensi come un difensore.", "Segunda caixa dominada! Você pensa como um defensor.", "Вторая коробка освоена! Ты мыслишь как защитник.", "第二个盒子拿下！你已经像个防守者在思考了。", "2つめのボックス制覇！守る人の考え方ができている。", "दूसरा बक्सा जीत लिया! तुम रक्षक की तरह सोचते हो।", "أتقنت الصندوق الثاني! تفكر كمدافع.", "দ্বিতীয় বাক্স আয়ত্তে! তুমি রক্ষীর মতো ভাবছ।", "Kotak kedua dikuasai! Kamu berpikir seperti pembela.", "دوسرا ڈبہ قابو میں! تم محافظ کی طرح سوچتے ہو۔"),
 "hist.cit14.5.adulte": T("L'inspecteur vérifie qu'aucun bit r (journal) ni w (ronde) n'est resté pour « o ».", "The inspector checks that no r bit (diary) or w bit (patrol) remains for “o”.", "El inspector verifica que no quede ningún bit r (diario) ni w (ronda) para «o».", "Der Inspektor prüft, dass für „o“ kein r-Bit (Tagebuch) und kein w-Bit (Runde) übrig ist.", "L'ispettore verifica che non resti alcun bit r (diario) né w (ronda) per «o».", "O inspetor confere que não sobrou nenhum bit r (diário) nem w (ronda) para «o».", "Инспектор проверяет, что у «o» не осталось бита r (дневник) и бита w (обход).", "检查员确认 o 已经没有 r 位（日记）和 w 位（巡逻）。", "検査官は「o」に r（日記）も w（見回り）も残っていないか確かめる。", "निरीक्षक जाँचता है कि «o» के लिए न r बिट (डायरी) बचा न w (गश्त)।", "يتحقق المفتش من عدم بقاء بت r (المذكرات) ولا w (الجولة) لـ «o».", "পরিদর্শক দেখে «o»-এর জন্য r (ডায়েরি) বা w (টহল) বিট বাকি নেই।", "Inspektur memeriksa tak ada bit r (buku harian) maupun w (patroli) tersisa untuk «o».", "انسپکٹر جانچتا ہے کہ «o» کے لیے نہ r بٹ (ڈائری) بچا نہ w (گشت)۔"),
 # ------------------------------------------------------------------ cit15 boîte Secrets oubliés
 "hist.cit15.0.dit": T("Boîte « Les secrets oubliés » : liste tout, fichiers cachés compris.", "Box “The forgotten secrets”: list everything, hidden files included.", "Caja «Los secretos olvidados»: lista todo, archivos ocultos incluidos.", "Kiste „Die vergessenen Geheimnisse“: Liste alles, versteckte Dateien inklusive.", "Scatola «I segreti dimenticati»: elenca tutto, file nascosti compresi.", "Caixa «Os segredos esquecidos»: liste tudo, arquivos ocultos inclusive.", "Коробка «Забытые секреты»: выведи всё, скрытые файлы тоже.", "盒子“被遗忘的秘密”：全部列出来，隐藏文件也算。", "ボックス「忘れられた秘密」：かくしファイルもふくめて全部表示しよう。", "बक्सा «भूले हुए राज़»: सब दिखाओ, छिपी फ़ाइलें भी।", "صندوق «الأسرار المنسية»: اعرض كل شيء بما فيه الملفات المخفية.", "বাক্স «ভুলে যাওয়া গোপন কথা»: সব দেখাও, লুকানো ফাইলসহ।", "Kotak «Rahasia yang terlupa»: tampilkan semua, termasuk berkas tersembunyi.", "ڈبہ «بھولے ہوئے راز»: سب دکھاؤ، چھپی فائلیں بھی۔"),
 "hist.cit15.0.bravo": T("Un .historique_fictif et un config.ini… Les secrets aiment ces endroits-là.", "A .historique_fictif and a config.ini… Secrets love places like these.", "Un .historique_fictif y un config.ini… A los secretos les encantan esos sitios.", "Eine .historique_fictif und eine config.ini … Geheimnisse lieben solche Orte.", "Un .historique_fictif e un config.ini… I segreti amano questi posti.", "Um .historique_fictif e um config.ini… Segredos adoram esses lugares.", ".historique_fictif и config.ini… Секреты любят такие места.", "一个 .historique_fictif 和一个 config.ini……秘密最爱藏在这种地方。", ".historique_fictif と config.ini……秘密はこういう場所が好き。", "एक .historique_fictif और एक config.ini… राज़ों को ऐसी जगहें पसंद हैं।", "‏.historique_fictif وconfig.ini… الأسرار تحب هذه الأماكن.", "একটা .historique_fictif আর একটা config.ini… গোপন কথা এমন জায়গা ভালোবাসে।", "Ada .historique_fictif dan config.ini… Rahasia suka tempat seperti ini.", "ایک .historique_fictif اور ایک config.ini… راز ایسی جگہیں پسند کرتے ہیں۔"),
 "hist.cit15.0.adulte": T("L'historique du shell (~/.bash_history) garde tout ce qui a été tapé, y compris un mot de passe écrit dans une commande. Ici, c'est un faux historique.", "The shell history (~/.bash_history) keeps everything typed, including a password written in a command. Here it is a fake history.", "El historial del shell (~/.bash_history) guarda todo lo tecleado, incluida una contraseña escrita en una orden. Aquí es un historial falso.", "Der Shell-Verlauf (~/.bash_history) speichert alles Getippte, auch ein Passwort in einem Befehl. Hier ist es ein falscher Verlauf.", "La cronologia della shell (~/.bash_history) conserva tutto ciò che è stato digitato, anche una password scritta in un comando. Qui è una cronologia finta.", "O histórico do shell (~/.bash_history) guarda tudo o que foi digitado, inclusive uma senha escrita num comando. Aqui é um histórico falso.", "История оболочки (~/.bash_history) хранит всё набранное, включая пароль внутри команды. Здесь — фальшивая история.", "shell 的历史记录（~/.bash_history）会保存所有敲过的东西，包括写在命令里的密码。这里是个假的历史记录。", "シェルの履歴（~/.bash_history）は打ったものを全部のこす。コマンドに書いたパスワードもふくめて。ここにあるのはニセの履歴。", "शेल का इतिहास (~/.bash_history) टाइप किया सब रखता है, कमांड में लिखा पासवर्ड भी। यहाँ यह नकली इतिहास है।", "يحفظ سجل الصدفة (~/.bash_history) كل ما كُتب، بما فيه كلمة مرور في أمر. هنا سجل مزيف.", "শেলের ইতিহাস (~/.bash_history) টাইপ করা সব রাখে, কমান্ডে লেখা পাসওয়ার্ডও। এখানে এটা নকল ইতিহাস।", "Riwayat shell (~/.bash_history) menyimpan semua yang diketik, termasuk kata sandi dalam perintah. Di sini riwayat palsu.", "شیل کا تاریخچہ (~/.bash_history) ٹائپ کیا سب رکھتا ہے، کمانڈ میں لکھا پاس ورڈ بھی۔ یہاں یہ جعلی تاریخچہ ہے۔"),
 "hist.cit15.1.dit": T("Cherche le mot mot_de_passe dans toute la boîte.", "Search the whole box for the word mot_de_passe (password).", "Busca la palabra mot_de_passe (contraseña) en toda la caja.", "Suche das Wort mot_de_passe (Passwort) in der ganzen Kiste.", "Cerca la parola mot_de_passe (password) in tutta la scatola.", "Procure a palavra mot_de_passe (senha) em toda a caixa.", "Найди слово mot_de_passe (пароль) по всей коробке.", "在整个盒子里找 mot_de_passe（密码）这个词。", "ボックス全体で mot_de_passe（パスワード）という言葉をさがそう。", "पूरे बक्से में mot_de_passe (पासवर्ड) शब्द ढूँढो।", "ابحث عن كلمة mot_de_passe (كلمة المرور) في الصندوق كله.", "পুরো বাক্সে mot_de_passe (পাসওয়ার্ড) শব্দটা খোঁজো।", "Cari kata mot_de_passe (kata sandi) di seluruh kotak.", "پورے ڈبے میں mot_de_passe (پاس ورڈ) لفظ ڈھونڈو۔"),
 "hist.cit15.1.bravo": T("Deux secrets en clair (des exemples du jeu) : un dans l'historique, un dans la config. Ce sont les drapeaux !", "Two plain-text secrets (game examples): one in the history, one in the config. They are the flags!", "Dos secretos en claro (ejemplos del juego): uno en el historial, otro en la config. ¡Son las banderas!", "Zwei Geheimnisse im Klartext (Spielbeispiele): eins im Verlauf, eins in der Config. Das sind die Flaggen!", "Due segreti in chiaro (esempi del gioco): uno nella cronologia, uno nella config. Sono le bandiere!", "Dois segredos às claras (exemplos do jogo): um no histórico, um na config. São as bandeiras!", "Два секрета открытым текстом (примеры игры): один в истории, другой в конфиге. Это и есть флаги!", "两个明文秘密（游戏里的例子）：一个在历史记录里，一个在配置里。它们就是旗！", "そのまま書かれた秘密が2つ（ゲームの例）：履歴にひとつ、設定にひとつ。これが旗！", "दो खुले राज़ (खेल के उदाहरण): एक इतिहास में, एक कॉन्फ़िग में। यही झंडे हैं!", "سرّان واضحان (أمثلة من اللعبة): واحد في السجل وآخر في الإعدادات. إنهما العلمان!", "দুটো খোলা গোপন কথা (খেলার উদাহরণ): একটা ইতিহাসে, একটা কনফিগে। এগুলোই পতাকা!", "Dua rahasia terang (contoh permainan): satu di riwayat, satu di config. Itulah benderanya!", "دو کھلے راز (کھیل کی مثالیں): ایک تاریخچے میں، ایک کنفیگ میں۔ یہی جھنڈے ہیں!"),
 "hist.cit15.1.adulte": T("Les secrets oubliés en clair (fichiers de config, historiques, sauvegardes) sont parmi les fuites les plus fréquentes ; des outils les cherchent automatiquement avant chaque publication.", "Forgotten plain-text secrets (config files, histories, backups) are among the most frequent leaks; tools scan for them automatically before each release.", "Los secretos olvidados en claro (configs, historiales, copias) están entre las fugas más frecuentes; hay herramientas que los buscan antes de cada publicación.", "Vergessene Klartext-Geheimnisse (Configs, Verläufe, Sicherungen) gehören zu den häufigsten Lecks; Werkzeuge suchen sie vor jeder Veröffentlichung.", "I segreti dimenticati in chiaro (config, cronologie, backup) sono tra le fughe più frequenti; strumenti li cercano prima di ogni pubblicazione.", "Segredos esquecidos às claras (configs, históricos, backups) estão entre os vazamentos mais comuns; ferramentas os procuram antes de cada publicação.", "Забытые открытые секреты (конфиги, истории, копии) — одни из самых частых утечек; инструменты ищут их перед каждой публикацией.", "忘在明处的秘密（配置文件、历史记录、备份）是最常见的泄露之一；有工具会在每次发布前自动扫描。", "そのままわすれられた秘密（設定、履歴、バックアップ）は、もっとも多いもれのひとつ。公開の前に自動でさがす道具がある。", "खुले में भूले राज़ (कॉन्फ़िग, इतिहास, बैकअप) सबसे आम रिसावों में हैं; हर प्रकाशन से पहले टूल इन्हें अपने-आप खोजते हैं।", "الأسرار المنسية الواضحة (الإعدادات، السجلات، النسخ) من أكثر التسريبات شيوعًا؛ وأدوات تبحث عنها تلقائيًا قبل كل نشر.", "খোলা ভুলে যাওয়া গোপন কথা (কনফিগ, ইতিহাস, ব্যাকআপ) সবচেয়ে সাধারণ ফাঁসের মধ্যে; প্রতিবার প্রকাশের আগে টুল আপনা থেকে খোঁজে।", "Rahasia terang yang terlupa (config, riwayat, cadangan) termasuk kebocoran paling sering; alat-alat memindainya otomatis sebelum tiap rilis.", "کھلے میں بھولے راز (کنفیگ، تاریخچے، بیک اپ) سب سے عام رساؤ میں ہیں؛ ہر اشاعت سے پہلے ٹول خود انہیں ڈھونڈتے ہیں۔"),
 "hist.cit15.2.dit": T("Rends les deux drapeaux (remplace ? par un drapeau, une fois chacun).", "Hand in both flags (replace ? with a flag, once each).", "Entrega las dos banderas (cambia ? por una bandera, una vez cada una).", "Gib beide Flaggen ab (ersetze ? durch eine Flagge, je einmal).", "Consegna le due bandiere (sostituisci ? con una bandiera, una volta ciascuna).", "Entregue as duas bandeiras (troque ? por uma bandeira, uma vez cada).", "Сдай оба флага (замени ? на флаг, по разу на каждый).", "交上两面旗（把 ? 换成旗，每面交一次）。", "旗を2つとも出そう（? を旗に変えて、1つずつ）。", "दोनों झंडे जमा करो (? की जगह झंडा, एक-एक बार)।", "سلّم العلمين (استبدل ? بعلم، مرة لكل واحد).", "দুটো পতাকাই জমা দাও (? এর জায়গায় পতাকা, একটা করে)।", "Serahkan kedua bendera (ganti ? dengan bendera, sekali masing-masing).", "دونوں جھنڈے جمع کرو (? کی جگہ جھنڈا، ایک ایک بار)۔"),
 "hist.cit15.2.bravo": T("Enquête finie. Rempart : effacer ce qui traîne, puis CHANGER le secret.", "Investigation done. Rampart: erase what's lying around, then CHANGE the secret.", "Investigación terminada. Muralla: borrar lo que sobra y luego CAMBIAR el secreto.", "Ermittlung fertig. Wall: Herumliegendes löschen, dann das Geheimnis ÄNDERN.", "Indagine finita. Bastione: cancellare ciò che resta in giro, poi CAMBIARE il segreto.", "Investigação concluída. Muralha: apagar o que está largado e depois TROCAR o segredo.", "Расследование окончено. Стена: стереть то, что валяется, и СМЕНИТЬ секрет.", "调查结束。城墙：先删掉乱放的，再把秘密换掉。", "調査おわり。城壁：ちらばったものを消して、秘密を変える。", "जाँच पूरी। प्राचीर: पड़ा हुआ मिटाओ, फिर राज़ बदलो।", "انتهى التحقيق. السور: امحُ ما هو مُلقى، ثم غيّر السر.", "তদন্ত শেষ। প্রাচীর: পড়ে থাকা মুছে ফেলো, তারপর গোপন কথা বদলাও।", "Penyelidikan selesai. Benteng: hapus yang tercecer, lalu GANTI rahasianya.", "تفتیش ختم۔ فصیل: پڑی چیز مٹاؤ، پھر راز بدلو۔"),
 "hist.cit15.2.adulte": T("Un secret qui a fuité est perdu, même si on l'efface ensuite : il faut le changer (rotation).", "A leaked secret is lost, even if you erase it afterwards: it must be changed (rotation).", "Un secreto filtrado está perdido aunque se borre después: hay que cambiarlo (rotación).", "Ein geleaktes Geheimnis ist verloren, auch wenn man es danach löscht: Es muss geändert werden (Rotation).", "Un segreto trapelato è perso anche se poi lo cancelli: va cambiato (rotazione).", "Um segredo vazado está perdido mesmo que seja apagado depois: é preciso trocá-lo (rotação).", "Утёкший секрет потерян, даже если потом его стереть: его надо сменить (ротация).", "泄露过的秘密就算删了也没用：必须换掉（轮换）。", "もれた秘密は、あとで消しても取りもどせない。変える必要がある（ローテーション）。", "लीक हुआ राज़ बाद में मिटाने पर भी गया: उसे बदलना पड़ता है (रोटेशन)।", "السر المسرّب ضائع حتى لو مُحي لاحقًا: يجب تغييره (تدوير).", "ফাঁস হওয়া গোপন কথা পরে মুছলেও হারানো: বদলাতে হয় (রোটেশন)।", "Rahasia yang bocor sudah hilang walau dihapus kemudian: harus diganti (rotasi).", "لیک ہوا راز بعد میں مٹانے پر بھی گیا: اسے بدلنا پڑتا ہے (روٹیشن)۔"),
 "hist.cit15.3.dit": T("Efface le faux historique qui garde le secret.", "Erase the fake history that keeps the secret.", "Borra el historial falso que guarda el secreto.", "Lösche den falschen Verlauf, der das Geheimnis enthält.", "Cancella la cronologia finta che conserva il segreto.", "Apague o histórico falso que guarda o segredo.", "Сотри фальшивую историю, где хранится секрет.", "删掉保存着秘密的假历史记录。", "秘密がのこったニセの履歴を消そう。", "राज़ रखने वाला नकली इतिहास मिटाओ।", "امحُ السجل المزيف الذي يحفظ السر.", "গোপন কথা রাখা নকল ইতিহাস মুছে ফেলো।", "Hapus riwayat palsu yang menyimpan rahasia.", "راز رکھنے والا جعلی تاریخچہ مٹاؤ۔"),
 "hist.cit15.3.bravo": T("Plus d'historique bavard.", "No more chatty history.", "Se acabó el historial charlatán.", "Kein geschwätziger Verlauf mehr.", "Niente più cronologia chiacchierona.", "Acabou o histórico tagarela.", "Болтливой истории больше нет.", "多嘴的历史记录没了。", "おしゃべりな履歴はもうない。", "बातूनी इतिहास अब नहीं।", "لا مزيد من السجل الثرثار.", "আর বাচাল ইতিহাস নেই।", "Tak ada lagi riwayat yang cerewet.", "اب باتونی تاریخچہ نہیں۔"),
 "hist.cit15.3.adulte": T("Pour ne pas écrire un secret dans l'historique : laisser le programme le demander (sans l'afficher), ou utiliser un gestionnaire de secrets.", "To avoid writing a secret into the history: let the program ask for it (without showing it), or use a secrets manager.", "Para no escribir un secreto en el historial: deja que el programa lo pida (sin mostrarlo) o usa un gestor de secretos.", "Damit kein Geheimnis im Verlauf landet: Lass das Programm danach fragen (ohne Anzeige) oder nutze einen Geheimnis-Manager.", "Per non scrivere un segreto nella cronologia: lascia che il programma lo chieda (senza mostrarlo) o usa un gestore di segreti.", "Para não escrever um segredo no histórico: deixe o programa pedir (sem mostrar) ou use um gerenciador de segredos.", "Чтобы секрет не попал в историю: пусть программа спросит его сама (не показывая) или используй менеджер секретов.", "想让秘密不进历史记录：让程序自己来问（不显示出来），或者用秘密管理工具。", "履歴に秘密を書かないために：プログラムに聞いてもらう（表示しない）か、秘密の管理ソフトを使う。", "राज़ इतिहास में न जाए: प्रोग्राम को खुद पूछने दो (बिना दिखाए), या राज़-प्रबंधक इस्तेमाल करो।", "كي لا يُكتب السر في السجل: دع البرنامج يطلبه (دون عرضه) أو استخدم مدير أسرار.", "গোপন কথা যেন ইতিহাসে না যায়: প্রোগ্রামকে চাইতে দাও (না দেখিয়ে), বা গোপন-কথা ম্যানেজার ব্যবহার করো।", "Agar rahasia tak masuk riwayat: biarkan program yang menanyakannya (tanpa ditampilkan), atau pakai pengelola rahasia.", "راز تاریخچے میں نہ جائے: پروگرام کو خود پوچھنے دو (بغیر دکھائے)، یا رازوں کا مینیجر استعمال کرو۔"),
 "hist.cit15.4.dit": T("Change le secret du pont-levis (la Citadelle en fabrique un nouvel exemple).", "Change the drawbridge secret (the Citadel makes a new example).", "Cambia el secreto del puente levadizo (la Ciudadela fabrica un nuevo ejemplo).", "Ändere das Geheimnis der Zugbrücke (die Zitadelle erzeugt ein neues Beispiel).", "Cambia il segreto del ponte levatoio (la Cittadella ne crea un nuovo esempio).", "Troque o segredo da ponte levadiça (a Cidadela cria um novo exemplo).", "Смени секрет подъёмного моста (Цитадель сделает новый пример).", "换掉吊桥的秘密（城堡会做一个新的例子）。", "はね橋の秘密を変えよう（城塞が新しい例を作る）。", "उठने वाले पुल का राज़ बदलो (किला नया उदाहरण बनाएगा)।", "غيّر سرّ الجسر المتحرك (تصنع القلعة مثالًا جديدًا).", "টানা সেতুর গোপন কথা বদলাও (দুর্গ নতুন উদাহরণ বানাবে)।", "Ganti rahasia jembatan angkat (Benteng membuat contoh baru).", "اٹھنے والے پل کا راز بدلو (قلعہ نئی مثال بنائے گا)۔"),
 "hist.cit15.4.bravo": T("Nouveau secret, rangé en 600. L'ancien drapeau ne marche plus : essaie, tu verras !", "New secret, stored as 600. The old flag no longer works: try it and see!", "Secreto nuevo, guardado en 600. La bandera antigua ya no sirve: ¡pruébalo!", "Neues Geheimnis, mit 600 abgelegt. Die alte Flagge funktioniert nicht mehr: Probier's aus!", "Nuovo segreto, salvato in 600. La vecchia bandiera non funziona più: prova e vedrai!", "Segredo novo, guardado em 600. A bandeira antiga não funciona mais: experimente!", "Новый секрет, лежит с правами 600. Старый флаг больше не работает: попробуй!", "新秘密，权限 600 收好。旧旗不能用了：不信你试试！", "新しい秘密を 600 でしまった。古い旗はもう使えない：ためしてごらん！", "नया राज़, 600 में रखा। पुराना झंडा अब काम नहीं करता: आज़माकर देखो!", "سر جديد محفوظ بـ 600. العلم القديم لم يعد يعمل: جرّب وسترى!", "নতুন গোপন কথা, 600-এ রাখা। পুরনো পতাকা আর কাজ করে না: চেষ্টা করে দেখো!", "Rahasia baru, disimpan 600. Bendera lama tak berlaku lagi: coba saja!", "نیا راز، 600 میں رکھا۔ پرانا جھنڈا اب کام نہیں کرتا: آزما کر دیکھو!"),
 "hist.cit15.4.adulte": T("Rotation : générer un nouveau secret, le stocker protégé (600), invalider l'ancien. Le jeu n'invente que des exemples.", "Rotation: generate a new secret, store it protected (600), invalidate the old one. The game only invents examples.", "Rotación: generar un secreto nuevo, guardarlo protegido (600), invalidar el antiguo. El juego solo inventa ejemplos.", "Rotation: neues Geheimnis erzeugen, geschützt ablegen (600), altes ungültig machen. Das Spiel erfindet nur Beispiele.", "Rotazione: generare un nuovo segreto, salvarlo protetto (600), invalidare il vecchio. Il gioco inventa solo esempi.", "Rotação: gerar um segredo novo, guardar protegido (600), invalidar o antigo. O jogo só inventa exemplos.", "Ротация: создать новый секрет, хранить защищённо (600), отменить старый. Игра придумывает только примеры.", "轮换：生成新秘密，受保护地存放（600），让旧的作废。游戏只编例子。", "ローテーション：新しい秘密を作り、守って保管し（600）、古いものを無効にする。ゲームは例しか作らない。", "रोटेशन: नया राज़ बनाओ, सुरक्षित रखो (600), पुराना रद्द करो। खेल सिर्फ़ उदाहरण बनाता है।", "التدوير: توليد سر جديد، حفظه محميًا (600)، إبطال القديم. اللعبة تخترع أمثلة فقط.", "রোটেশন: নতুন গোপন কথা বানাও, সুরক্ষিত রাখো (600), পুরনোটা বাতিল করো। খেলা শুধু উদাহরণ বানায়।", "Rotasi: buat rahasia baru, simpan terlindungi (600), batalkan yang lama. Permainan hanya mengarang contoh.", "روٹیشن: نیا راز بناؤ، محفوظ رکھو (600)، پرانا منسوخ کرو۔ کھیل صرف مثالیں بناتا ہے۔"),
 "hist.cit15.5.dit": T("Appelle l'inspecteur pour la boîte des secrets.", "Call the inspector for the secrets box.", "Llama al inspector para la caja de secretos.", "Ruf den Inspektor für die Geheimnis-Kiste.", "Chiama l'ispettore per la scatola dei segreti.", "Chame o inspetor para a caixa dos segredos.", "Позови инспектора для коробки секретов.", "叫检查员来查秘密盒子。", "秘密のボックスに検査官を呼ぼう。", "राज़ों वाले बक्से के लिए निरीक्षक बुलाओ।", "استدعِ المفتش لصندوق الأسرار.", "গোপন কথার বাক্সের জন্য পরিদর্শক ডাকো।", "Panggil inspektur untuk kotak rahasia.", "رازوں والے ڈبے کے لیے انسپکٹر بلاؤ۔"),
 "hist.cit15.5.bravo": T("Trois boîtes maîtrisées ! Il ne reste que la grande vague.", "Three boxes mastered! Only the great wave remains.", "¡Tres cajas dominadas! Solo queda la gran ola.", "Drei Kisten gemeistert! Nur die große Welle bleibt.", "Tre scatole padroneggiate! Resta solo la grande ondata.", "Três caixas dominadas! Só falta a grande onda.", "Три коробки освоены! Осталась только большая волна.", "三个盒子都拿下了！只剩大浪潮了。", "ボックス3つ制覇！のこるは大波だけ。", "तीन बक्से जीत लिए! बस बड़ी लहर बाकी है।", "أتقنت ثلاثة صناديق! بقيت الموجة الكبرى فقط.", "তিনটা বাক্স আয়ত্তে! শুধু বড় ঢেউ বাকি।", "Tiga kotak dikuasai! Tinggal gelombang besar.", "تین ڈبے قابو میں! بس بڑی لہر باقی ہے۔"),
 "hist.cit15.5.adulte": T("L'inspecteur vérifie : historique effacé, config.ini fermée aux autres, secret changé.", "The inspector checks: history erased, config.ini closed to others, secret changed.", "El inspector verifica: historial borrado, config.ini cerrado a los demás, secreto cambiado.", "Der Inspektor prüft: Verlauf gelöscht, config.ini für andere zu, Geheimnis geändert.", "L'ispettore verifica: cronologia cancellata, config.ini chiuso agli altri, segreto cambiato.", "O inspetor confere: histórico apagado, config.ini fechado aos outros, segredo trocado.", "Инспектор проверяет: история стёрта, config.ini закрыт для остальных, секрет сменён.", "检查员核对：历史记录删了，config.ini 对其他人关上了，秘密换了。", "検査官が確かめる：履歴は消えた、config.ini はその他に閉じた、秘密は変わった。", "निरीक्षक जाँचता है: इतिहास मिटा, config.ini बाकी के लिए बंद, राज़ बदला।", "يتحقق المفتش: السجل ممحو، وconfig.ini مغلق أمام الآخرين، والسر مُغيَّر.", "পরিদর্শক যাচাই করে: ইতিহাস মোছা, config.ini অন্যদের জন্য বন্ধ, গোপন কথা বদলানো।", "Inspektur memeriksa: riwayat terhapus, config.ini tertutup untuk lainnya, rahasia diganti.", "انسپکٹر جانچتا ہے: تاریخچہ مٹا، config.ini باقی کے لیے بند، راز بدلا۔"),
 # ------------------------------------------------------------------ cit16 la grande vague (pare-feu, tableau)
 "hist.cit16.0.dit": T("Avant la vague : quelles portes de ton ordinateur sont ouvertes ? (En lecture seulement.)", "Before the wave: which doors of your computer are open? (Read-only.)", "Antes de la ola: ¿qué puertas de tu ordenador están abiertas? (Solo lectura.)", "Vor der Welle: Welche Türen deines Computers sind offen? (Nur lesen.)", "Prima dell'ondata: quali porte del tuo computer sono aperte? (Solo lettura.)", "Antes da onda: quais portas do seu computador estão abertas? (Só leitura.)", "Перед волной: какие двери твоего компьютера открыты? (Только посмотреть.)", "大浪来之前：你电脑上有哪些门是开着的？（只看不改。）", "大波の前に：きみのコンピュータのどの扉が開いている？（見るだけ。）", "लहर से पहले: तुम्हारे कंप्यूटर के कौन-से दरवाज़े खुले हैं? (सिर्फ़ देखना।)", "قبل الموجة: ما الأبواب المفتوحة في حاسوبك؟ (للقراءة فقط.)", "ঢেউয়ের আগে: তোমার কম্পিউটারের কোন দরজাগুলো খোলা? (শুধু দেখা।)", "Sebelum gelombang: pintu mana di komputermu yang terbuka? (Hanya dibaca.)", "لہر سے پہلے: تمہارے کمپیوٹر کے کون سے دروازے کھلے ہیں؟ (صرف دیکھنا۔)"),
 "hist.cit16.0.bravo": T("Chaque ligne LISTEN est une porte qui écoute. Un pare-feu, c'est la liste des portes qu'on laisse ouvertes, et à qui.", "Each LISTEN line is a door that listens. A firewall is the list of doors we leave open, and to whom.", "Cada línea LISTEN es una puerta que escucha. Un cortafuegos es la lista de puertas que dejamos abiertas, y a quién.", "Jede LISTEN-Zeile ist eine lauschende Tür. Eine Firewall ist die Liste der Türen, die wir offen lassen, und für wen.", "Ogni riga LISTEN è una porta in ascolto. Un firewall è la lista delle porte che lasciamo aperte, e a chi.", "Cada linha LISTEN é uma porta que escuta. Um firewall é a lista das portas que deixamos abertas, e para quem.", "Каждая строка LISTEN — слушающая дверь. Межсетевой экран — это список дверей, которые мы оставляем открытыми, и для кого.", "每一行 LISTEN 就是一扇在“听”的门。防火墙就是一张清单：哪些门开着、对谁开。", "LISTEN の行は、聞き耳を立てている扉。ファイアウォールは、どの扉をだれに開けておくかのリスト。", "हर LISTEN पंक्ति एक सुनता हुआ दरवाज़ा है। फ़ायरवॉल यानी कौन-से दरवाज़े खुले रहें और किसके लिए, इसकी सूची।", "كل سطر LISTEN باب يستمع. الجدار الناري هو قائمة الأبواب التي نتركها مفتوحة، ولمن.", "প্রতিটা LISTEN লাইন একটা শোনার দরজা। ফায়ারওয়াল মানে কোন দরজা খোলা থাকবে আর কার জন্য, তার তালিকা।", "Tiap baris LISTEN adalah pintu yang mendengarkan. Firewall adalah daftar pintu yang dibiarkan terbuka, dan untuk siapa.", "ہر LISTEN سطر ایک سنتا دروازہ ہے۔ فائر وال یعنی کون سے دروازے کھلے رہیں اور کس کے لیے، اس کی فہرست۔"),
 "hist.cit16.0.adulte": T("ss -tln liste les ports TCP en écoute ; 127.0.0.1 = seulement cette machine, 0.0.0.0 = tout le réseau. On ne fait que lire : régler le vrai pare-feu (nftables) demande root.", "ss -tln lists listening TCP ports; 127.0.0.1 = this machine only, 0.0.0.0 = the whole network. We only read: setting the real firewall (nftables) needs root.", "ss -tln lista los puertos TCP en escucha; 127.0.0.1 = solo esta máquina, 0.0.0.0 = toda la red. Solo leemos: ajustar el cortafuegos real (nftables) requiere root.", "ss -tln listet lauschende TCP-Ports; 127.0.0.1 = nur dieser Rechner, 0.0.0.0 = das ganze Netz. Wir lesen nur: Die echte Firewall (nftables) braucht root.", "ss -tln elenca le porte TCP in ascolto; 127.0.0.1 = solo questa macchina, 0.0.0.0 = tutta la rete. Leggiamo soltanto: configurare il vero firewall (nftables) richiede root.", "ss -tln lista as portas TCP em escuta; 127.0.0.1 = só esta máquina, 0.0.0.0 = a rede toda. Só lemos: ajustar o firewall real (nftables) exige root.", "ss -tln показывает слушающие TCP-порты; 127.0.0.1 — только эта машина, 0.0.0.0 — вся сеть. Мы только читаем: настраивать настоящий экран (nftables) может root.", "ss -tln 列出正在监听的 TCP 端口；127.0.0.1 = 只有本机，0.0.0.0 = 整个网络。我们只看：真的防火墙（nftables）要 root 才能改。", "ss -tln は待ち受け中の TCP ポートを表示する。127.0.0.1＝このマシンだけ、0.0.0.0＝ネットワーク全体。見るだけ：本物のファイアウォール（nftables）の設定には root が要る。", "ss -tln सुनते हुए TCP पोर्ट दिखाता है; 127.0.0.1 = सिर्फ़ यह मशीन, 0.0.0.0 = पूरा नेटवर्क। हम सिर्फ़ पढ़ते हैं: असली फ़ायरवॉल (nftables) के लिए root चाहिए।", "يعرض ss -tln منافذ TCP المستمعة؛ 127.0.0.1 = هذا الجهاز فقط، 0.0.0.0 = الشبكة كلها. نقرأ فقط: ضبط الجدار الناري الحقيقي (nftables) يتطلب root.", "ss -tln শোনার TCP পোর্ট দেখায়; 127.0.0.1 = শুধু এই যন্ত্র, 0.0.0.0 = পুরো নেটওয়ার্ক। আমরা শুধু পড়ি: আসল ফায়ারওয়াল (nftables) ঠিক করতে root লাগে।", "ss -tln menampilkan port TCP yang mendengarkan; 127.0.0.1 = mesin ini saja, 0.0.0.0 = seluruh jaringan. Kita hanya membaca: mengatur firewall sungguhan (nftables) butuh root.", "ss -tln سنتے TCP پورٹ دکھاتا ہے؛ 127.0.0.1 = صرف یہ مشین، 0.0.0.0 = پورا نیٹ ورک۔ ہم صرف پڑھتے ہیں: اصل فائر وال (nftables) کے لیے root چاہیے۔"),
 "hist.cit16.1.dit": T("Déclenche la grande vague d'entraînement (tout est faux, tout reste dans la Citadelle).", "Start the great training wave (everything is fake, everything stays in the Citadel).", "Lanza la gran ola de entrenamiento (todo es falso, todo queda en la Ciudadela).", "Starte die große Übungswelle (alles unecht, alles bleibt in der Zitadelle).", "Lancia la grande ondata d'allenamento (tutto è finto, tutto resta nella Cittadella).", "Lance a grande onda de treino (tudo é falso, tudo fica na Cidadela).", "Запусти большую учебную волну (всё ненастоящее, всё остаётся в Цитадели).", "发动一场大型训练浪潮（全是假的，全都留在城堡里）。", "練習用の大波をはじめよう（ぜんぶニセモノ、ぜんぶ城塞の中）。", "अभ्यास की बड़ी लहर शुरू करो (सब नकली, सब किले के अंदर)।", "أطلق موجة التدريب الكبرى (كلها مزيفة، وكلها تبقى في القلعة).", "অনুশীলনের বড় ঢেউ শুরু করো (সব নকল, সব দুর্গের ভেতরে)।", "Mulai gelombang latihan besar (semuanya palsu, semuanya tetap di Benteng).", "مشق کی بڑی لہر شروع کرو (سب جعلی، سب قلعے کے اندر)۔"),
 "hist.cit16.1.bravo": T("🌊 Des glitchs partout, un fantôme, un secret laissé ouvert ! Utilise tout ce que tu sais, puis regarde le tableau.", "🌊 Glitches everywhere, a ghost, a secret left open! Use everything you know, then check the board.", "🌊 ¡Glitches por todas partes, un fantasma, un secreto abierto! Usa todo lo que sabes y mira el tablero.", "🌊 Überall Glitches, ein Geist, ein offenes Geheimnis! Nutze alles, was du weißt, dann schau auf die Tafel.", "🌊 Glitch ovunque, un fantasma, un segreto lasciato aperto! Usa tutto ciò che sai, poi guarda il tabellone.", "🌊 Glitches por toda parte, um fantasma, um segredo aberto! Use tudo o que sabe e veja o painel.", "🌊 Глитчи повсюду, призрак, открытый секрет! Применяй всё, что знаешь, и смотри на табло.", "🌊 到处是故障怪，还有一个幽灵，一个没锁好的秘密！用上你学会的所有本事，再看看板。", "🌊 グリッチだらけ、ゆうれいがひとつ、開けっぱなしの秘密！知っていることを全部使って、ボードを見よう。", "🌊 हर जगह ग्लिच, एक भूत, एक खुला राज़! जो जानते हो सब इस्तेमाल करो, फिर बोर्ड देखो।", "🌊 خلل في كل مكان، شبح، سر مفتوح! استخدم كل ما تعرفه ثم انظر إلى اللوحة.", "🌊 সব জায়গায় গ্লিচ, একটা ভূত, একটা খোলা গোপন কথা! যা জানো সব কাজে লাগাও, তারপর বোর্ড দেখো।", "🌊 Glitch di mana-mana, satu hantu, satu rahasia terbuka! Pakai semua yang kamu tahu, lalu lihat papannya.", "🌊 ہر جگہ گلچ، ایک بھوت، ایک کھلا راز! جو جانتے ہو سب استعمال کرو، پھر بورڈ دیکھو۔"),
 "hist.cit16.1.adulte": T("La vague combine C2 (find -delete), C4 (ps/kill) et une fuite (chmod 600). C'est un exercice « blue team » : défendre son propre terrain.", "The wave combines C2 (find -delete), C4 (ps/kill) and a leak (chmod 600). It's a “blue team” exercise: defending your own ground.", "La ola combina C2 (find -delete), C4 (ps/kill) y una fuga (chmod 600). Es un ejercicio «blue team»: defender el propio terreno.", "Die Welle kombiniert C2 (find -delete), C4 (ps/kill) und ein Leck (chmod 600). Eine „Blue Team“-Übung: das eigene Gelände verteidigen.", "L'ondata combina C2 (find -delete), C4 (ps/kill) e una fuga (chmod 600). È un esercizio «blue team»: difendere il proprio terreno.", "A onda combina C2 (find -delete), C4 (ps/kill) e um vazamento (chmod 600). É um exercício «blue team»: defender o próprio terreno.", "Волна сочетает C2 (find -delete), C4 (ps/kill) и утечку (chmod 600). Это упражнение «blue team»: защита своей территории.", "浪潮结合了 C2（find -delete）、C4（ps/kill）和一次泄露（chmod 600）。这是“蓝队”练习：保卫自己的地盘。", "大波は C2（find -delete）、C4（ps/kill）、もれ（chmod 600）の組み合わせ。「ブルーチーム」の練習：自分の場所を守る。", "लहर में C2 (find -delete), C4 (ps/kill) और एक रिसाव (chmod 600) मिले हैं। यह «ब्लू टीम» अभ्यास है: अपना मैदान बचाना।", "تجمع الموجة C2 (find -delete) وC4 (ps/kill) وتسريبًا (chmod 600). إنه تمرين «الفريق الأزرق»: الدفاع عن أرضك.", "ঢেউয়ে C2 (find -delete), C4 (ps/kill) আর একটা ফাঁস (chmod 600) মিশে আছে। এটা «ব্লু টিম» অনুশীলন: নিজের মাঠ রক্ষা।", "Gelombang menggabungkan C2 (find -delete), C4 (ps/kill), dan kebocoran (chmod 600). Ini latihan «tim biru»: mempertahankan lahan sendiri.", "لہر میں C2 (find -delete)، C4 (ps/kill) اور ایک رساؤ (chmod 600) ملے ہیں۔ یہ «بلیو ٹیم» مشق ہے: اپنا میدان بچانا۔"),
 "hist.cit16.2.dit": T("Quand tu as tout réparé, regarde le tableau de garde : tout doit être vert.", "When you've fixed everything, check the guard board: everything must be green.", "Cuando lo hayas reparado todo, mira el tablero de guardia: todo debe estar en verde.", "Wenn du alles repariert hast, schau auf die Wachtafel: Alles muss grün sein.", "Quando hai riparato tutto, guarda il tabellone di guardia: tutto deve essere verde.", "Quando tiver consertado tudo, veja o painel de guarda: tudo tem de estar verde.", "Когда всё починишь, посмотри на табло караула: всё должно быть зелёным.", "全都修好以后，看看值班看板：必须全是绿的。", "全部直したら見張りボードを見よう：ぜんぶ緑でなければならない。", "सब ठीक कर लो तो पहरा-बोर्ड देखो: सब हरा होना चाहिए।", "عندما تصلح كل شيء، انظر إلى لوحة الحراسة: يجب أن يكون كل شيء أخضر.", "সব সারানো হলে পাহারা-বোর্ড দেখো: সব সবুজ হতে হবে।", "Kalau semua sudah diperbaiki, lihat papan jaga: semua harus hijau.", "سب ٹھیک کر لو تو پہرا بورڈ دیکھو: سب سبز ہونا چاہیے۔"),
 "hist.cit16.2.bravo": T("Vague repoussée ! Les tours de la Citadelle s'allument une à une.", "Wave pushed back! The Citadel's towers light up one by one.", "¡Ola rechazada! Las torres de la Ciudadela se encienden una a una.", "Welle abgewehrt! Die Türme der Zitadelle leuchten einer nach dem anderen auf.", "Ondata respinta! Le torri della Cittadella si accendono una a una.", "Onda repelida! As torres da Cidadela se acendem uma a uma.", "Волна отбита! Башни Цитадели загораются одна за другой.", "浪潮被击退！城堡的塔楼一座座亮了起来。", "大波を押し返した！城塞の塔がひとつずつ光る。", "लहर पीछे धकेल दी! किले की मीनारें एक-एक कर जगमगाती हैं।", "صُدّت الموجة! أبراج القلعة تضيء واحدًا تلو الآخر.", "ঢেউ ঠেকানো গেছে! দুর্গের মিনারগুলো একে একে জ্বলে উঠছে।", "Gelombang dihalau! Menara Benteng menyala satu per satu.", "لہر پسپا! قلعے کے مینار ایک ایک کر کے جگمگا اٹھے۔"),
 "hist.cit16.2.adulte": T("Défendre, c'est une boucle : détecter (journaux, tableau), réagir (arrêter, effacer, fermer), restaurer, puis vérifier.", "Defending is a loop: detect (logs, board), respond (stop, erase, close), restore, then verify.", "Defender es un ciclo: detectar (registros, tablero), reaccionar (detener, borrar, cerrar), restaurar y verificar.", "Verteidigen ist eine Schleife: erkennen (Protokolle, Tafel), reagieren (stoppen, löschen, schließen), wiederherstellen, prüfen.", "Difendere è un ciclo: rilevare (registri, tabellone), reagire (fermare, cancellare, chiudere), ripristinare, poi verificare.", "Defender é um ciclo: detectar (registros, painel), reagir (parar, apagar, fechar), restaurar e conferir.", "Защита — это цикл: обнаружить (журналы, табло), отреагировать (остановить, удалить, закрыть), восстановить, проверить.", "防守是一个循环：发现（日志、看板）、应对（停掉、删除、关上）、恢复，再核对。", "守ることはくり返し：見つける（記録、ボード）、対応する（止める、消す、閉める）、もどす、確かめる。", "बचाव एक चक्र है: पहचानो (लॉग, बोर्ड), जवाब दो (रोको, मिटाओ, बंद करो), वापस लाओ, फिर जाँचो।", "الدفاع حلقة: اكتشف (السجلات، اللوحة)، استجب (أوقف، امحُ، أغلق)، استعد، ثم تحقق.", "রক্ষা একটা চক্র: ধরো (লগ, বোর্ড), সাড়া দাও (থামাও, মোছো, বন্ধ করো), ফেরাও, তারপর যাচাই করো।", "Bertahan adalah siklus: deteksi (log, papan), tanggapi (hentikan, hapus, tutup), pulihkan, lalu periksa.", "دفاع ایک چکر ہے: پہچانو (لاگ، بورڈ)، ردعمل دو (روکو، مٹاؤ، بند کرو)، واپس لاؤ، پھر جانچو۔"),
}
